@layer base {
  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    padding: 0;
    background-color: #03060c;
    color: #e2e8f0;
    font-family: 'Silkscreen', 'Press Start 2P', monospace;
    overflow-x: hidden;
  }

  /* Pixelated rendering for retro sprites */
  .pixelated {
    image-rendering: pixelated;
    image-rendering: -moz-crisp-edges;
    image-rendering: crisp-edges;
  }
}

/* Custom Cosmic Scrollbars */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: #070c18;
}

::-webkit-scrollbar-thumb {
  background: #1a294d;
  border-radius: 4px;
  border: 1px solid rgba(0, 240, 255, 0.2);
}

::-webkit-scrollbar-thumb:hover {
  background: #00f0ff;
}

/* Subtle Sci-Fi CRT scanline overlay (non-intrusive) */
.crt-overlay::after {
  content: " ";
  display: block;
  position: absolute;
  top: 0; left: 0; bottom: 0; right: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%);
  background-size: 100% 4px;
  z-index: 50;
  pointer-events: none;
  opacity: 0.15;
}

/* 8-point grid background visualization helper */
.grid-8pt {
  background-size: 16px 16px;
  background-image: 
    linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
}

