import React, { useEffect, useRef } from 'react';

/**
 * High-performance 60fps HTML5 Canvas deep-space background.
 * Renders parallax starfields, nebula glow shaders, cosmic dust,
 * and shooting stars that dynamically react to current sector & difficulty.
 */
export default function CosmicBackground({ activeSector = 1, difficulty = 'Cadet' }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animationFrameId;

    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
      initStars();
    };
    window.addEventListener('resize', handleResize);

    // Dynamic color palettes per sector
    const sectorNebulaColors = {
      1: { primary: 'rgba(255, 110, 0, 0.12)', secondary: 'rgba(255, 170, 0, 0.08)', center: [0.25, 0.4] },
      2: { primary: 'rgba(0, 240, 255, 0.12)', secondary: 'rgba(56, 189, 248, 0.08)', center: [0.75, 0.3] },
      3: { primary: 'rgba(168, 85, 247, 0.13)', secondary: 'rgba(236, 72, 153, 0.07)', center: [0.3, 0.7] },
      4: { primary: 'rgba(16, 185, 129, 0.12)', secondary: 'rgba(52, 211, 153, 0.08)', center: [0.8, 0.65] },
      5: { primary: 'rgba(59, 130, 246, 0.13)', secondary: 'rgba(99, 102, 241, 0.08)', center: [0.5, 0.45] },
      6: { primary: 'rgba(244, 63, 94, 0.14)', secondary: 'rgba(225, 29, 72, 0.09)', center: [0.5, 0.5] }
    };

    // Starfield layers (depth parallax)
    const STAR_COUNT = 180;
    let stars = [];
    let cosmicDust = [];
    let shootingStars = [];

    const initStars = () => {
      stars = [];
      for (let i = 0; i < STAR_COUNT; i++) {
        stars.push({
          x: Math.random() * width,
          y: Math.random() * height,
          radius: Math.random() * 1.5 + 0.3,
          depth: Math.random() * 3 + 1,
          alpha: Math.random() * 0.7 + 0.3,
          twinkleSpeed: Math.random() * 0.03 + 0.008,
          phase: Math.random() * Math.PI * 2,
          isBright: Math.random() < 0.08
        });
      }

      // Cosmic dust particles
      cosmicDust = [];
      for (let i = 0; i < 40; i++) {
        cosmicDust.push({
          x: Math.random() * width,
          y: Math.random() * height,
          vx: (Math.random() - 0.5) * 0.2,
          vy: (Math.random() - 0.5) * 0.2,
          size: Math.random() * 2 + 1,
          alpha: Math.random() * 0.4 + 0.1
        });
      }
    };

    initStars();

    let lastShootingStarTime = 0;

    const maybeAddShootingStar = (time) => {
      if (time - lastShootingStarTime > 4000 && Math.random() < 0.03) {
        lastShootingStarTime = time;
        shootingStars.push({
          x: Math.random() * width * 0.8,
          y: Math.random() * height * 0.4,
          length: Math.random() * 80 + 40,
          speed: Math.random() * 12 + 10,
          angle: (Math.PI / 4) + (Math.random() - 0.5) * 0.2,
          life: 1,
          decay: 0.02
        });
      }
    };

    let tick = 0;

    const render = (time) => {
      tick += 0.01;
      maybeAddShootingStar(time);

      // Deep space base
      ctx.fillStyle = '#03060c';
      ctx.fillRect(0, 0, width, height);

      // Procedural sector nebula
      const palette = sectorNebulaColors[activeSector] || sectorNebulaColors[1];
      const nebX = width * palette.center[0] + Math.sin(tick * 0.5) * 20;
      const nebY = height * palette.center[1] + Math.cos(tick * 0.4) * 20;
      const nebRadius = Math.max(width, height) * 0.45;

      const grad = ctx.createRadialGradient(nebX, nebY, 10, nebX, nebY, nebRadius);
      grad.addColorStop(0, palette.primary);
      grad.addColorStop(0.5, palette.secondary);
      grad.addColorStop(1, 'rgba(3, 6, 12, 0)');

      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, width, height);

      // Render Stars with twinkling
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        s.phase += s.twinkleSpeed;
        const currentAlpha = Math.max(0.2, s.alpha + Math.sin(s.phase) * 0.35);

        ctx.fillStyle = `rgba(240, 246, 255, ${currentAlpha})`;
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
        ctx.fill();

        if (s.isBright) {
          // Cross flare for brightest stars
          ctx.strokeStyle = `rgba(0, 240, 255, ${currentAlpha * 0.4})`;
          ctx.lineWidth = 0.75;
          ctx.beginPath();
          ctx.moveTo(s.x - s.radius * 3, s.y);
          ctx.lineTo(s.x + s.radius * 3, s.y);
          ctx.moveTo(s.x, s.y - s.radius * 3);
          ctx.lineTo(s.x, s.y + s.radius * 3);
          ctx.stroke();
        }
      }

      // Render Cosmic Dust
      for (let i = 0; i < cosmicDust.length; i++) {
        const d = cosmicDust[i];
        d.x += d.vx;
        d.y += d.vy;
        if (d.x < 0) d.x = width;
        if (d.x > width) d.x = 0;
        if (d.y < 0) d.y = height;
        if (d.y > height) d.y = 0;

        ctx.fillStyle = `rgba(200, 225, 255, ${d.alpha})`;
        ctx.beginPath();
        ctx.arc(d.x, d.y, d.size, 0, Math.PI * 2);
        ctx.fill();
      }

      // Render Shooting Stars
      for (let i = shootingStars.length - 1; i >= 0; i--) {
        const ss = shootingStars[i];
        const tailX = ss.x - Math.cos(ss.angle) * ss.length;
        const tailY = ss.y - Math.sin(ss.angle) * ss.length;

        const sGrad = ctx.createLinearGradient(ss.x, ss.y, tailX, tailY);
        sGrad.addColorStop(0, `rgba(255, 255, 255, ${ss.life})`);
        sGrad.addColorStop(0.3, `rgba(0, 240, 255, ${ss.life * 0.8})`);
        sGrad.addColorStop(1, 'rgba(0, 240, 255, 0)');

        ctx.strokeStyle = sGrad;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(ss.x, ss.y);
        ctx.lineTo(tailX, tailY);
        ctx.stroke();

        ss.x += Math.cos(ss.angle) * ss.speed;
        ss.y += Math.sin(ss.angle) * ss.speed;
        ss.life -= ss.decay;

        if (ss.life <= 0) {
          shootingStars.splice(i, 1);
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
    };
  }, [activeSector, difficulty]);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 pointer-events-none z-0"
      style={{ display: 'block' }}
    />
  );
}

