    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let animationFrameId;

    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
      initStars();
    };
    window.addEventListener('resize', handleResize);

    const sectorGlows = {
      1: { primary: 'rgba(255, 107, 0, 0.09)', secondary: 'rgba(245, 158, 11, 0.05)' },
      2: { primary: 'rgba(0, 240, 255, 0.09)', secondary: 'rgba(56, 189, 248, 0.05)' },
      3: { primary: 'rgba(168, 85, 247, 0.10)', secondary: 'rgba(236, 72, 153, 0.05)' },
      4: { primary: 'rgba(16, 185, 129, 0.09)', secondary: 'rgba(52, 211, 153, 0.05)' },
      5: { primary: 'rgba(59, 130, 246, 0.09)', secondary: 'rgba(99, 102, 241, 0.05)' },
      6: { primary: 'rgba(244, 63, 94, 0.10)', secondary: 'rgba(225, 29, 72, 0.05)' }
    };

    const STAR_COUNT = bgMode === 'minimal' ? 90 : 160;
    let stars = [];
    let shootingStars = [];

    const initStars = () => {
      stars = [];
      for (let i = 0; i < STAR_COUNT; i++) {
        stars.push({
          x: Math.random() * width,
          y: Math.random() * height,
          vx: (Math.random() - 0.5) * 0.15,
          vy: (Math.random() - 0.5) * 0.15,
          radius: Math.random() * 1.4 + 0.3,
          alpha: Math.random() * 0.6 + 0.2,
          twinkleSpeed: Math.random() * 0.025 + 0.008,
          phase: Math.random() * Math.PI * 2,
          isConstellation: Math.random() < 0.25
        });
      }
    };

    initStars();

    let lastShootingStarTime = 0;

    const maybeAddMeteor = (time) => {
      const interval = bgMode === 'meteor' ? 1200 : 5000;
      if (time - lastShootingStarTime > interval) {
        lastShootingStarTime = time;
        shootingStars.push({
          x: Math.random() * width * 0.9,
          y: Math.random() * height * 0.4,
          length: Math.random() * 90 + 50,
          speed: Math.random() * 14 + 10,
          angle: (Math.PI / 4) + (Math.random() - 0.5) * 0.3,
          life: 1,
          decay: 0.02
        });
      }
    };

    let tick = 0;

    const render = (time) => {
      tick += 0.008;

      if (bgMode === 'meteor' || bgMode === 'stargazing') {
        maybeAddMeteor(time);
      }

      // Pure Charcoal Black Canvas Base
      ctx.fillStyle = '#090a0d';
      ctx.fillRect(0, 0, width, height);

      // 1. Nebula / Ambient sector glow
      if (bgMode !== 'minimal') {
        const palette = sectorGlows[activeSector] || sectorGlows[1];
        const nebX = width * 0.5 + Math.sin(tick * 0.7) * 35;
        const nebY = height * 0.45 + Math.cos(tick * 0.6) * 25;
        const nebRadius = Math.max(width, height) * 0.5;

        const grad = ctx.createRadialGradient(nebX, nebY, 20, nebX, nebY, nebRadius);
        grad.addColorStop(0, palette.primary);
        grad.addColorStop(0.55, palette.secondary);
        grad.addColorStop(1, 'rgba(9, 10, 13, 0)');

        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, width, height);
      }

