      if (bgMode === 'stargazing') {
        ctx.lineWidth = 0.5;
        const constellationStars = stars.filter(s => s.isConstellation);
        for (let i = 0; i < constellationStars.length; i++) {
          for (let j = i + 1; j < constellationStars.length; j++) {
            const s1 = constellationStars[i];
            const s2 = constellationStars[j];
            const dx = s1.x - s2.x;
            const dy = s1.y - s2.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            // Connect nearby stars with delicate celestial lines
            if (dist < 110) {
              const lineAlpha = (1 - dist / 110) * 0.18;
              ctx.strokeStyle = `rgba(0, 240, 255, ${lineAlpha})`;
              ctx.beginPath();
              ctx.moveTo(s1.x, s1.y);
              ctx.lineTo(s2.x, s2.y);
              ctx.stroke();
            }
          }
        }

        // Faint Observatory Coordinate Reticle in center
        ctx.strokeStyle = 'rgba(0, 240, 255, 0.03)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(width / 2, height / 2, 280, 0, Math.PI * 2);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(width / 2, height / 2, 420, 0, Math.PI * 2);
        ctx.stroke();
      }

      // 3. Render Stars
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        s.phase += s.twinkleSpeed;
        const currentAlpha = Math.max(0.12, s.alpha + Math.sin(s.phase) * 0.3);

        // Drift slowly in stargazing mode
        if (bgMode === 'stargazing') {
          s.x += s.vx;
          s.y += s.vy;
          if (s.x < 0) s.x = width;
          if (s.x > width) s.x = 0;
          if (s.y < 0) s.y = height;
          if (s.y > height) s.y = 0;
        }

        ctx.fillStyle = s.isConstellation && bgMode === 'stargazing'
          ? `rgba(0, 240, 255, ${currentAlpha * 1.2})`
          : `rgba(235, 240, 255, ${currentAlpha})`;

        ctx.beginPath();
        ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
        ctx.fill();
      }

