              ctx.strokeStyle = `rgba(0, 240, 255, ${lineAlpha})`;
              ctx.beginPath();
              ctx.moveTo(s1.x, s1.y);
              ctx.lineTo(s2.x, s2.y);
              ctx.stroke();
            }
          }
        }

        // Faint Observatory Coordinate Reticle in center
        ctx.strokeStyle = 'rgba(0, 240, 255, 0.025)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(width / 2, height / 2, 280, 0, Math.PI * 2);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(width / 2, height / 2, 420, 0, Math.PI * 2);
        ctx.stroke();
      }

      // 3. Render Natural Pinpoint Stars
      for (let i = 0; i < stars.length; i++) {
        const s = stars[i];
        s.phase += s.twinkleSpeed;
        const currentAlpha = Math.max(0.12, s.alpha + Math.sin(s.phase) * 0.28);

        // Drift slowly in stargazing mode
        if (bgMode === 'stargazing') {
          s.x += s.vx;
          s.y += s.vy;
          if (s.x < 0) s.x = width;
          if (s.x > width) s.x = 0;
          if (s.y < 0) s.y = height;
          if (s.y > height) s.y = 0;
        }

        ctx.fillStyle = s.isConstellation && bgMode === 'stargazing'
          ? `rgba(0, 240, 255, ${currentAlpha * 0.95})`
          : `rgba(240, 245, 255, ${currentAlpha * 0.85})`;

        ctx.beginPath();
        ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
        ctx.fill();
      }

      // 4. Render Meteor Shower / Shooting Stars
      for (let i = shootingStars.length - 1; i >= 0; i--) {
        const ss = shootingStars[i];
        const tailX = ss.x - Math.cos(ss.angle) * ss.length;
        const tailY = ss.y - Math.sin(ss.angle) * ss.length;

        const sGrad = ctx.createLinearGradient(ss.x, ss.y, tailX, tailY);
        sGrad.addColorStop(0, `rgba(255, 255, 255, ${ss.life})`);
        sGrad.addColorStop(0.35, `rgba(0, 240, 255, ${ss.life * 0.75})`);
        sGrad.addColorStop(1, 'rgba(0, 240, 255, 0)');

        ctx.strokeStyle = sGrad;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(ss.x, ss.y);
        ctx.lineTo(tailX, tailY);
        ctx.stroke();

        ss.x += Math.cos(ss.angle) * ss.speed;
        ss.y += Math.sin(ss.angle) * ss.speed;
        ss.life -= ss.decay;

        if (ss.life <= 0) {
          shootingStars.splice(i, 1);
        }
      }

      // 5. Update Free-Floating Astronaut Physics (Roaming smoothly across the background)
      const a = astronautState.current;
      a.x += a.vx;
      a.y += a.vy;

      // Buoyant zero-g swaying
      const swayY = Math.sin(tick * 2.2) * 5;
      const swayAngle = Math.sin(tick * 1.4) * 10;
      const currentAngle = a.angle + swayAngle + a.spin;

      if (Math.abs(a.spin) > 0.05) {
        a.spin *= 0.95;
      }

      // Soft boundary steering so astronaut wanders freely across the entire viewport
      const padX = 60;
      const padY = 50;
      if (a.x < padX) {
        a.vx = Math.abs(a.vx) * 0.96 + 0.1;
        a.angle = -8;
      } else if (a.x > width - padX - 80) {
        a.vx = -Math.abs(a.vx) * 0.96 - 0.1;
        a.angle = -22;
      }

      if (a.y < padY) {
        a.vy = Math.abs(a.vy) * 0.96 + 0.1;
      } else if (a.y > height - padY - 80) {
        a.vy = -Math.abs(a.vy) * 0.96 - 0.1;
      }

      // Subtle random steering drift
      if (Math.random() < 0.015) {
        a.vx += (Math.random() - 0.5) * 0.15;
        a.vy += (Math.random() - 0.5) * 0.15;
        const spd = Math.hypot(a.vx, a.vy);
        if (spd > 1.2) {
          a.vx = (a.vx / spd) * 1.2;
          a.vy = (a.vy / spd) * 1.2;
        } else if (spd < 0.35) {
          a.vx = (a.vx / (spd || 1)) * 0.5;
          a.vy = (a.vy / (spd || 1)) * 0.5;
        }
      }

      if (astronautRef.current) {
        astronautRef.current.style.transform = `translate3d(${a.x}px, ${a.y + swayY}px, 0px) rotate(${currentAngle}deg)`;
      }

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
    };
  }, [activeSector, bgMode]);

  const handleAstronautBoost = (e) => {
    e.stopPropagation();
    soundFx.playPass();
    setIsTapped(true);
