import React from 'react';
import { 
  Trophy, 
  Target, 
  Sparkles, 
  Volume2, 
  VolumeX, 
  Map, 
  Code2, 
  ShieldCheck, 
  LogOut
} from 'lucide-react';
import { soundFx } from '../services/soundFx';
import { getRankForXp, getNextRank } from '../data/curriculum';

export default function HUD({
  currentUser,
  userProgress,
  activeView,
  setActiveView,
  isMuted,
  setIsMuted,
  onOpenProfile,
  onLogout
}) {
  const currentRank = getRankForXp(userProgress.xp);
  const nextRank = getNextRank(currentRank.level);

  // Calculate XP progress within current level
  const currentLevelBaseXp = currentRank.xpRequired;
  const nextLevelBaseXp = nextRank ? nextRank.xpRequired : currentLevelBaseXp + 1000;
  const xpInCurrentLevel = Math.max(0, userProgress.xp - currentLevelBaseXp);
  const xpNeededForNext = nextLevelBaseXp - currentLevelBaseXp;
  const progressPercent = Math.min(100, Math.round((xpInCurrentLevel / xpNeededForNext) * 100));

  const handleToggleSound = () => {
    const muted = soundFx.toggleMute();
    setIsMuted(muted);
    if (!muted) soundFx.playClick();
  };

  return (
    <header className="sticky top-0 z-40 w-full bg-charcoal-950/90 backdrop-blur-md border-b border-charcoal-750/80 shadow-hud select-none">
      <div className="max-w-[1920px] mx-auto px-3 sm:px-6 h-16 flex items-center justify-between gap-3 sm:gap-6">

        {/* Left Section: User Profile & Identity */}
        <div className="flex items-center gap-3 min-w-[220px]">
          {/* Avatar Thumbnail */}
          <div 
            onClick={onOpenProfile}
            className="group relative cursor-pointer flex items-center justify-center p-1 rounded-xl bg-charcoal-900 border border-charcoal-700 hover:border-cosmic-cyan transition-all duration-200 box-glow-cyan"
            title="Open Flight Log & Dossier"
          >
            <div className="relative w-9 h-9 bg-charcoal-850 rounded-lg overflow-hidden flex items-center justify-center">
              <img 
                src={currentUser?.avatar || '/sprites/astronaut_idle.png'} 
                alt="Avatar" 
                className="w-8 h-8 object-contain pixelated group-hover:scale-105 transition-transform" 
              />
              <span className="absolute bottom-0.5 right-0.5 w-2 h-2 bg-cosmic-emerald rounded-full ring-2 ring-charcoal-950 animate-pulse" />
            </div>
            {currentUser?.role === 'student' && (
              <span className="absolute -top-1.5 -right-1.5 px-1 py-0.2 rounded bg-cosmic-orange text-charcoal-950 text-[9px] font-pixel font-bold shadow-md">
                LV.{currentRank.level}
              </span>
            )}
          </div>

          {/* User Name & Rank */}
          <div className="flex flex-col">
            <div className="flex items-center gap-1.5">
              <span className="text-xs font-pixel font-bold text-slate-100 truncate max-w-[130px] sm:max-w-[180px]">
                {currentUser?.name || 'Space Cadet'}
              </span>
            </div>
            <div className="flex items-center gap-1 text-[11px] font-retro text-slate-400">
              <span className="text-cosmic-amber">{currentRank.badge}</span>
              <span className="text-cosmic-amber font-semibold truncate max-w-[140px]">
                {currentUser?.role === 'admin' ? 'Faculty Admin' : currentRank.title}
              </span>
            </div>
          </div>
        </div>

        {/* Center Section: Fluid XP Progress Bar (Shown for students) */}
        {currentUser?.role === 'student' && (
          <div className="flex-1 max-w-md mx-2 hidden md:flex flex-col gap-1">
            <div className="flex items-center justify-between text-[11px] font-retro">
              <div className="flex items-center gap-1 text-slate-300">
                <Sparkles className="w-3 h-3 text-cosmic-cyan animate-pulse" />
                <span>TOTAL XP:</span>
                <span className="font-pixel text-cosmic-cyan text-[10px]">{userProgress.xp}</span>
              </div>

              <div className="flex items-center gap-1 text-slate-400 text-[10px]">
                <span>NEXT:</span>
                <span className="text-cosmic-orange font-semibold">
                  {nextRank ? `${userProgress.xp}/${nextLevelBaseXp} XP` : 'MAX'}
                </span>
              </div>
            </div>

            <div className="relative w-full h-2.5 bg-charcoal-900 rounded-full border border-charcoal-750 overflow-hidden">
              <div 
                className="h-full rounded-full bg-gradient-to-r from-cosmic-cyan via-cosmic-blue to-cosmic-orange transition-all duration-500 ease-out"
                style={{ width: `${progressPercent}%` }}
              />
            </div>
          </div>
        )}

        {/* Right Section: Navigation, Telemetry & Controls */}
        <div className="flex items-center gap-2 sm:gap-3">

          {/* Quick Metrics */}
          {currentUser?.role === 'student' && (
            <div className="hidden lg:flex items-center gap-3 bg-charcoal-900 border border-charcoal-750 px-3 py-1.5 rounded-xl text-xs font-retro">
              <div className="flex items-center gap-1.5 border-r border-charcoal-750 pr-3">
                <Trophy className="w-3.5 h-3.5 text-cosmic-amber" />
                <span className="text-slate-400 text-[10px]">CLEARED:</span>
                <span className="font-pixel text-[10px] text-cosmic-amber">{userProgress.clearedProblems.length}/21</span>
              </div>

              <div className="flex items-center gap-1.5">
                <Target className="w-3.5 h-3.5 text-cosmic-cyan" />
                <span className="text-slate-400 text-[10px]">TRIED:</span>
                <span className="font-pixel text-[10px] text-cosmic-cyan">{userProgress.attemptedProblems.length}/21</span>
              </div>
            </div>
          )}

          {/* Navigation View Toggles */}
          <div className="flex items-center bg-charcoal-900 p-1 rounded-xl border border-charcoal-750 gap-1 text-xs font-retro">
            <button
              onClick={() => { soundFx.playClick(); setActiveView('map'); }}
              className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg transition-all ${
                activeView === 'map'
                  ? 'bg-cosmic-cyan text-charcoal-950 font-bold shadow-glow-cyan'
                  : 'text-slate-300 hover:text-white hover:bg-charcoal-800'
              }`}
            >
              <Map className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">STAR MAP</span>
            </button>

            <button
              onClick={() => { soundFx.playClick(); setActiveView('workspace'); }}
              className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg transition-all ${
                activeView === 'workspace'
                  ? 'bg-cosmic-orange text-charcoal-950 font-bold shadow-glow-orange'
                  : 'text-slate-300 hover:text-white hover:bg-charcoal-800'
              }`}
            >
              <Code2 className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">WORKSPACE</span>
            </button>

            {currentUser?.role === 'admin' && (
              <button
                onClick={() => { soundFx.playClick(); setActiveView('admin'); }}
                className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg transition-all ${
                  activeView === 'admin'
                    ? 'bg-cosmic-purple text-charcoal-950 font-bold shadow-glow-purple'
                    : 'text-slate-300 hover:text-white hover:bg-charcoal-800'
                }`}
              >
                <ShieldCheck className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">FACULTY DECK</span>
              </button>
            )}
          </div>

          {/* Audio Synthesizer Mute Toggle */}
          <button
            onClick={handleToggleSound}
            className={`p-2 rounded-xl border transition-all ${
              isMuted
                ? 'bg-charcoal-900 border-charcoal-750 text-slate-500'
                : 'bg-charcoal-900 border-cosmic-cyan/40 text-cosmic-cyan hover:border-cosmic-cyan box-glow-cyan'
            }`}
            title={isMuted ? 'Unmute Audio' : 'Mute Audio'}
          >
            {isMuted ? <VolumeX className="w-3.5 h-3.5" /> : <Volume2 className="w-3.5 h-3.5" />}
          </button>

          {/* Logout / Switch Role Button */}
          <button
            onClick={() => {
              soundFx.playClick();
              if (confirm('Log out and return to Gateway Terminal?')) {
                onLogout();
              }
            }}
            className="p-2 rounded-xl bg-charcoal-900 border border-charcoal-750 text-slate-400 hover:text-red-400 hover:border-red-900 transition-colors"
            title="Log Out / Switch Account"
          >
            <LogOut className="w-3.5 h-3.5" />
          </button>
        </div>

      </div>
    </header>
  );
}

