              <span className="absolute bottom-0.5 right-0.5 w-2 h-2 bg-cosmic-emerald rounded-full ring-2 ring-charcoal-950 animate-pulse" />
            </div>
            {currentUser?.role === 'student' && (
              <span className="absolute -top-1.5 -right-1.5 px-1 py-0.2 rounded bg-cosmic-orange text-charcoal-950 text-[9px] font-pixel font-bold shadow-md">
