                className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg transition-all ${
                  activeView === 'admin'
                    ? 'bg-cosmic-purple text-charcoal-950 font-bold shadow-glow-purple'
                    : 'text-slate-300 hover:text-white hover:bg-charcoal-800'
                }`}
              >
                <ShieldCheck className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">FACULTY DECK</span>
              </button>
            )}
          </div>

          {/* Stargazing Background Effect Switcher */}
          <button
            onClick={handleCycleBg}
            className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl bg-charcoal-900 border border-charcoal-750 text-slate-300 hover:border-cosmic-cyan hover:text-cosmic-cyan transition-colors text-xs font-retro"
            title={`Background Effect: ${curBg.label} (Click to change)`}
          >
            <span>{curBg.icon}</span>
            <span className="hidden lg:inline text-[10px] font-pixel">{curBg.label}</span>
          </button>

          {/* Audio Synthesizer Mute Toggle */}
          <button
            onClick={handleToggleSound}
            className={`p-2 rounded-xl border transition-all ${
              isMuted
                ? 'bg-charcoal-900 border-charcoal-750 text-slate-500'
                : 'bg-charcoal-900 border-cosmic-cyan/40 text-cosmic-cyan hover:border-cosmic-cyan box-glow-cyan'
            }`}
            title={isMuted ? 'Unmute Audio' : 'Mute Audio'}
          >
            {isMuted ? <VolumeX className="w-3.5 h-3.5" /> : <Volume2 className="w-3.5 h-3.5" />}
          </button>

          {/* Logout / Switch Role Button */}
          <button
            onClick={() => {
              soundFx.playClick();
              if (confirm('Log out and return to Gateway Terminal?')) {
                onLogout();
              }
            }}
            className="p-2 rounded-xl bg-charcoal-900 border border-charcoal-750 text-slate-400 hover:text-red-400 hover:border-red-900 transition-colors"
            title="Log Out / Switch Account"
          >
            <LogOut className="w-3.5 h-3.5" />
          </button>
        </div>

      </div>
    </header>
  );
}

