import React, { useState, useEffect, useRef } from 'react';
import { 
  Lock, 
  Unlock, 
  ChevronRight, 
  Sparkles, 
  CheckCircle2, 
  AlertCircle, 
  Play, 
  Zap,
  Compass
} from 'lucide-react';
import { MODULES, PROBLEMS, getRankForXp } from '../data/curriculum';
import { soundFx } from '../services/soundFx';

export default function SpaceMap({ 
  userProgress, 
  onSelectProblem, 
  currentSectorId, 
  setCurrentSectorId 
}) {
  const [selectedModule, setSelectedModule] = useState(null);
  const [avatarPos, setAvatarPos] = useState({ x: 120, y: 340 });
  const [isTraveling, setIsTraveling] = useState(false);
  const [avatarSprite, setAvatarSprite] = useState('/sprites/astronaut_idle.png');
  const [travelProgress, setTravelProgress] = useState(1); // 0 to 1
  const mapContainerRef = useRef(null);

  const currentRank = getRankForXp(userProgress.xp);

  // Determine if a module is unlocked
  const isModuleUnlocked = (mod) => {
    return currentRank.level >= mod.minLevelToUnlock || userProgress.xp >= mod.minXpToUnlock;
  };

  // Find target coordinates for current sector on load
  useEffect(() => {
    const curMod = MODULES.find(m => m.id === currentSectorId) || MODULES[0];
    setAvatarPos(curMod.coordinates);
  }, [currentSectorId]);

  // Spline Path Interpolation for Smooth Character Transitions (no teleporting!)
  const travelToModule = (targetMod) => {
    if (!isModuleUnlocked(targetMod) || isTraveling) {
      if (!isModuleUnlocked(targetMod)) soundFx.playFail();
      return;
    }

    soundFx.playWarp();
    setIsTraveling(true);
    setAvatarSprite('/sprites/astronaut_walking.png');

    const startMod = MODULES.find(m => m.id === currentSectorId) || MODULES[0];
    setCurrentSectorId(targetMod.id);

    // Parametric cubic spline interpolation points
    const p0 = startMod.coordinates;
    const p3 = targetMod.coordinates;

    // Smooth control points
    const midX = (p0.x + p3.x) / 2;
    const p1 = { x: midX, y: p0.y - 60 };
    const p2 = { x: midX, y: p3.y + 60 };

    const duration = 1400; // ms
    const startTime = performance.now();

    const animateStep = (now) => {
      const elapsed = now - startTime;
      const t = Math.min(1, elapsed / duration);

      // Smooth cubic bezier easing
      const easeT = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

      // Cubic Bezier spline formula: B(t) = (1-t)^3 P0 + 3(1-t)^2 t P1 + 3(1-t) t^2 P2 + t^3 P3
      const u = 1 - easeT;
      const x = u * u * u * p0.x + 3 * u * u * easeT * p1.x + 3 * u * easeT * easeT * p2.x + easeT * easeT * easeT * p3.x;
      const y = u * u * u * p0.y + 3 * u * u * easeT * p1.y + 3 * u * easeT * easeT * p2.y + easeT * easeT * easeT * p3.y;

      setAvatarPos({ x, y });
      setTravelProgress(easeT);

      if (t < 1) {
        requestAnimationFrame(animateStep);
      } else {
        setAvatarPos(p3);
        setIsTraveling(false);
        setAvatarSprite('/sprites/astronaut_cheering.png');
        soundFx.playPass();
        setTimeout(() => {
          setAvatarSprite('/sprites/astronaut_idle.png');
        }, 1200);
      }
    };

    requestAnimationFrame(animateStep);
  };

  // SVG Cubic Bezier Path Generator connecting consecutive planetary nodes
  const renderOrbitalPaths = () => {
    return MODULES.slice(0, -1).map((mod, idx) => {
      const nextMod = MODULES[idx + 1];
      const p0 = mod.coordinates;
      const p3 = nextMod.coordinates;
      const midX = (p0.x + p3.x) / 2;
      const p1 = { x: midX, y: p0.y - 60 };
      const p2 = { x: midX, y: p3.y + 60 };

      const isPathActive = isModuleUnlocked(nextMod);

      const d = `M ${p0.x} ${p0.y} C ${p1.x} ${p1.y}, ${p2.x} ${p2.y}, ${p3.x} ${p3.y}`;

      return (
        <g key={`path-${mod.id}-${nextMod.id}`}>
          {/* Base energy track */}
          <path
            d={d}
            fill="none"
            stroke={isPathActive ? 'rgba(0, 240, 255, 0.25)' : 'rgba(75, 85, 99, 0.3)'}
            strokeWidth="3"
            strokeDasharray={isPathActive ? '8 6' : '4 6'}
          />
          {/* Animated pulsing spline stream if active */}
          {isPathActive && (
            <path
              d={d}
              fill="none"
              stroke="#00f0ff"
              strokeWidth="2"
              strokeDasharray="12 12"
              className="opacity-70 animate-pulse"
            />
          )}
        </g>
      );
    });
  };

  return (
    <div className="relative w-full h-[calc(100vh-4.5rem)] overflow-hidden select-none flex flex-col justify-between p-4 sm:p-6 lg:p-8">

      {/* Map Header Overlay with Sector Coordinates */}
      <div className="z-10 flex items-center justify-between pointer-events-none">
        <div className="flex flex-col gap-1 pointer-events-auto bg-space-950/80 backdrop-blur-md p-3 rounded-lg border border-space-700/80">
          <div className="flex items-center gap-2">
            <Compass className="w-4 h-4 text-cosmic-cyan animate-spin-slow" />
            <h1 className="text-xs sm:text-sm font-pixel text-cosmic-cyan tracking-wider">
              2D COSMIC PROGRESSION MAP
            </h1>
          </div>
          <p className="text-[11px] font-retro text-slate-400">
            Click an unlocked planetary sector to dispatch your astronaut and solve syllabus lab modules.
          </p>
        </div>

        {/* Legend */}
        <div className="hidden md:flex items-center gap-4 bg-space-950/80 backdrop-blur-md px-3 py-2 rounded-lg border border-space-700/80 text-xs font-retro text-slate-300">
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-cosmic-cyan" />
            <span>Unlocked</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-slate-600" />
            <span>Cosmic Fog (Locked)</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-cosmic-emerald" />
            <span>Completed</span>
          </div>
        </div>
      </div>

      {/* Main 2D Star Map Interactive Canvas Area */}
      <div 
        ref={mapContainerRef}
        className="relative flex-1 w-full max-w-7xl mx-auto my-4 overflow-x-auto overflow-y-hidden border border-space-800/80 rounded-2xl bg-space-950/50 backdrop-blur-sm grid-8pt shadow-2xl min-h-[500px]"
      >
        <div className="relative w-[1380px] h-[520px]">

          {/* Orbital Spline Connection Paths */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none">
            {renderOrbitalPaths()}
          </svg>

          {/* Planetary Sector Nodes */}
          {MODULES.map((mod) => {
            const unlocked = isModuleUnlocked(mod);
            const isCurrent = currentSectorId === mod.id;
            const modProblems = PROBLEMS.filter(p => p.moduleId === mod.id);
            const solvedInMod = modProblems.filter(p => userProgress.clearedProblems.includes(p.id));
            const isFullySolved = modProblems.length > 0 && solvedInMod.length === modProblems.length;

            return (
              <div
                key={mod.id}
                style={{
                  left: `${mod.coordinates.x}px`,
                  top: `${mod.coordinates.y}px`,
                  transform: 'translate(-50%, -50%)'
                }}
                className="absolute z-20 flex flex-col items-center group cursor-pointer"
                onClick={() => {
                  if (unlocked) {
                    travelToModule(mod);
                    setSelectedModule(mod);
                  } else {
                    soundFx.playFail();
                  }
                }}
              >
                {/* Planet Celestial Orb */}
                <div className="relative">
                  {/* Cosmic Fog Overlay for Locked Sectors */}
                  {!unlocked && (
                    <div 
                      className="absolute -inset-6 rounded-full blur-xl pointer-events-none z-30 opacity-70"
                      style={{ background: 'radial-gradient(circle, rgba(100,116,139,0.4) 0%, rgba(3,6,12,0.9) 70%)' }}
                    />
                  )}

                  {/* Active Sector Pulsing Halo */}
                  {isCurrent && (
                    <div 
                      className="absolute -inset-4 rounded-full animate-ping opacity-35"
                      style={{ border: `2px solid ${mod.accent}` }}
                    />
                  )}

                  {/* Core Planet Sphere */}
                  <div 
                    className={`relative w-20 h-20 rounded-full flex items-center justify-center transition-all duration-300 ${
                      unlocked 
                        ? 'hover:scale-110 shadow-lg' 
                        : 'opacity-40 grayscale filter'
                    }`}
                    style={{
                      background: unlocked
                        ? `radial-gradient(circle at 35% 35%, ${mod.accent}, ${mod.color} 60%, #03060c 95%)`
                        : '#1e293b',
                      boxShadow: unlocked ? `0 0 25px ${mod.color}66` : 'none',
                      border: isCurrent ? `2px solid ${mod.accent}` : '1px solid rgba(255,255,255,0.15)'
                    }}
                  >
                    {/* Planet Ring details */}
                    <div className="absolute inset-0 rounded-full border border-white/20 transform rotate-45 scale-125 pointer-events-none opacity-40" />

                    {/* Sector Code / State Icon */}
                    <div className="z-10 flex flex-col items-center justify-center text-center">
                      {!unlocked ? (
                        <Lock className="w-6 h-6 text-slate-400" />
                      ) : isFullySolved ? (
                        <CheckCircle2 className="w-7 h-7 text-white" />
                      ) : (
                        <span className="font-pixel text-xs text-white drop-shadow-md">
                          M{mod.id}
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                {/* Planet Label & Info Plate */}
                <div className="mt-3 flex flex-col items-center bg-space-900/90 border border-space-700/80 px-2.5 py-1 rounded-md text-center max-w-[150px] shadow-md group-hover:border-cosmic-cyan transition-colors">
                  <span className="text-[10px] font-pixel text-slate-200 truncate w-full">
                    {mod.sectorName}
                  </span>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <span className="text-[9px] font-retro text-cosmic-cyan">
                      {solvedInMod.length}/{modProblems.length} SOLVED
                    </span>
                  </div>
                </div>

                {/* Locked Tooltip */}
                {!unlocked && (
                  <div className="absolute -bottom-8 px-2 py-0.5 rounded bg-space-950/95 border border-red-500/50 text-[9px] font-retro text-red-400 whitespace-nowrap z-40">
                    REQ LV.{mod.minLevelToUnlock} ({mod.minXpToUnlock} XP)
                  </div>
                )}
              </div>
            );
          })}

          {/* 2D Pixel-Art Astronaut Avatar (Smooth spline-interpolated motion) */}
          <div
            style={{
              left: `${avatarPos.x}px`,
              top: `${avatarPos.y - 48}px`,
              transform: 'translate(-50%, -50%)',
              transition: isTraveling ? 'none' : 'transform 0.3s ease-out'
            }}
            className="absolute z-30 pointer-events-none flex flex-col items-center"
          >
            {/* Astronaut Sprite */}
            <div className="relative w-18 h-18">
              <img
                src={avatarSprite}
                alt="Player Astronaut"
                className={`w-full h-full object-contain pixelated drop-shadow-[0_8px_16px_rgba(0,240,255,0.6)] ${
                  isTraveling ? 'animate-bounce' : 'animate-float'
                }`}
              />
            </div>

            {/* Astronaut Callout Tag */}
            <div className="px-2 py-0.5 rounded-full bg-space-950/95 border border-cosmic-cyan text-[9px] font-pixel text-cosmic-cyan shadow-md mt-1">
              YOU
            </div>
          </div>

        </div>
      </div>

      {/* Selected Sector Mission Drawer / Modal */}
      {selectedModule && (
        <div className="z-30 bg-space-900/95 backdrop-blur-md border border-space-700 rounded-xl p-4 sm:p-6 shadow-2xl max-w-5xl mx-auto w-full transition-all duration-300">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 border-b border-space-800 pb-3 mb-4">
