import React, { useState, useRef, useEffect } from 'react';
import Editor from '@monaco-editor/react';
import confetti from 'canvas-confetti';
import { 
  Play, 
  Send, 
  HelpCircle, 
  RotateCcw, 
  CheckCircle, 
  XCircle, 
  Clock, 
  AlertTriangle,
  Code, 
  Terminal, 
  Maximize2, 
  Sparkles, 
  Split,
  ChevronDown,
  ChevronUp,
  FileCode,
  Zap,
  Info
} from 'lucide-react';
import { soundFx } from '../services/soundFx';
import { cEngine } from '../services/cEngine';

export default function Workspace({ 
  problem, 
  userProgress, 
  onProblemSolved, 
  onBackToMap,
  onDeductXp
}) {
  const [code, setCode] = useState(problem.starterCode);
  const [splitRatio, setSplitRatio] = useState(38.2); // Golden Ratio default: 38.2% / 61.8%
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState('problem'); // 'problem' | 'hints'
  const [outputTab, setOutputTab] = useState('testcases'); // 'testcases' | 'terminal'

  // Execution status
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [evalResult, setEvalResult] = useState(null);
  const [selectedTestCaseIdx, setSelectedTestCaseIdx] = useState(0);
  const [astronautReaction, setAstronautReaction] = useState('/sprites/astronaut_floating.png');

  // Hint management
  const [unlockedHintLevels, setUnlockedHintLevels] = useState([]);
  const [showHintModal, setShowHintModal] = useState(false);

  const containerRef = useRef(null);

  // Sync state when problem changes
  useEffect(() => {
    setCode(problem.starterCode);
    setEvalResult(null);
    setSelectedTestCaseIdx(0);
    setAstronautReaction('/sprites/astronaut_floating.png');
    setUnlockedHintLevels([]);
  }, [problem.id]);

  // Handle Dragging Split-Pane Handle with 60fps pointer events
  const handlePointerDown = (e) => {
    e.preventDefault();
    setIsDragging(true);
    soundFx.playClick();
  };

  useEffect(() => {
    const handlePointerMove = (e) => {
      if (!isDragging || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const pointerX = e.clientX - rect.left;
      const newRatio = (pointerX / rect.width) * 100;
      // Clamp between 20% and 80%
      if (newRatio >= 20 && newRatio <= 80) {
        setSplitRatio(newRatio);
      }
    };

    const handlePointerUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    if (isDragging) {
      window.addEventListener('pointermove', handlePointerMove);
      window.addEventListener('pointerup', handlePointerUp);
    }
    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [isDragging]);

  // Golden Ratio Preset Snap
  const snapToGoldenRatio = () => {
    soundFx.playClick();
    setSplitRatio(38.2); // (1 - 1/1.618) * 100%
  };

  const snapToEqual = () => {
    soundFx.playClick();
    setSplitRatio(50);
  };

  // Run Code / Submit Code
  const handleExecute = async (isSubmission = true) => {
    soundFx.playCompile();
    setIsEvaluating(true);
    setAstronautReaction('/sprites/astronaut_typing.png');
    setOutputTab('testcases');

    try {
      // Evaluate using high-performance C Engine
      const res = await cEngine.evaluateSubmission(problem, code);
      setIsEvaluating(false);
      setEvalResult(res);

      if (res.allPassed) {
        soundFx.playPass();
        soundFx.playLevelUp();
        setAstronautReaction('/sprites/astronaut_cheering.png');

        // Confetti celebration
        confetti({
          particleCount: 100,
          spread: 70,
          origin: { y: 0.6 }
        });

        if (isSubmission) {
          onProblemSolved(problem.id, res.earnedXp);
        }
      } else {
        soundFx.playFail();
        setAstronautReaction('/sprites/astronaut_hint.png');
      }
    } catch (err) {
      setIsEvaluating(false);
      soundFx.playFail();
      setAstronautReaction('/sprites/astronaut_hint.png');
      setEvalResult({
        allPassed: false,
        compilationError: err.message,
        results: []
      });
    }
  };

  // Hint Purchase Logic
  const handleUnlockHint = (hint) => {
    if (unlockedHintLevels.includes(hint.level)) return;
    if (userProgress.xp < hint.cost) {
      soundFx.playFail();
      alert(`Insufficient XP! You need ${hint.cost} XP to unlock this hint.`);
      return;
    }
    soundFx.playWarp();
    onDeductXp(hint.cost);
    setUnlockedHintLevels([...unlockedHintLevels, hint.level]);
    setShowHintModal(false);
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-[calc(100vh-4.5rem)] flex flex-col md:flex-row overflow-hidden bg-space-950 select-none ${
        isDragging ? 'cursor-col-resize' : ''
      }`}
    >

      {/* ================= LEFT PANE: Problem Statement Panel (Golden Ratio ~38.2%) ================= */}
      <div 
        style={{ width: `${splitRatio}%` }}
        className="h-full flex flex-col border-r border-space-800 bg-space-900/60 backdrop-blur-md overflow-hidden"
      >
        {/* Panel Header */}
        <div className="h-14 px-4 bg-space-950/80 border-b border-space-800 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-cosmic-cyan animate-pulse" />
            <h2 className="text-xs font-pixel text-slate-100 truncate max-w-[200px] sm:max-w-[280px]">
              {problem.title}
            </h2>
          </div>
          <span className="text-[10px] font-retro px-2 py-0.5 rounded bg-cosmic-orange/20 border border-cosmic-orange text-cosmic-orange">
            +{problem.xpReward} XP
          </span>
        </div>

        {/* Tab Switcher: Problem Statement / Hints */}
        <div className="flex items-center border-b border-space-800 bg-space-900 text-xs font-retro">
          <button
            onClick={() => { soundFx.playClick(); setActiveTab('problem'); }}
            className={`flex-1 py-2 text-center transition-colors ${
              activeTab === 'problem'
                ? 'border-b-2 border-cosmic-cyan text-cosmic-cyan font-bold bg-space-850'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            BRIEFING & SPECS
          </button>
          <button
            onClick={() => { soundFx.playClick(); setActiveTab('hints'); }}
            className={`flex-1 py-2 text-center transition-colors flex items-center justify-center gap-1.5 ${
              activeTab === 'hints'
                ? 'border-b-2 border-cosmic-amber text-cosmic-amber font-bold bg-space-850'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            <HelpCircle className="w-3.5 h-3.5" />
            <span>HINTS ({unlockedHintLevels.length}/{problem.hints.length})</span>
          </button>
        </div>

        {/* Panel Body: Scrollable Content */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-5 text-xs text-slate-300 font-retro space-y-4">
          {activeTab === 'problem' ? (
            <>
              {/* Mission Badge & Syllabus Reference */}
              <div className="flex items-center justify-between bg-space-850 p-2.5 rounded-lg border border-space-700/80">
                <span className="text-slate-400">SYLLABUS REF:</span>
                <span className="text-cosmic-cyan font-semibold">{problem.syllabusRef}</span>
              </div>

              {/* Problem Description */}
              <div className="space-y-2">
                <h3 className="font-pixel text-[11px] text-cosmic-cyan tracking-wider">
                  MISSION OBJECTIVE
                </h3>
                <p className="leading-relaxed whitespace-pre-wrap text-slate-200">
                  {problem.description}
                </p>
              </div>

              {/* Input & Output Format */}
              <div className="space-y-3 pt-2">
                <div className="bg-space-950/70 p-3 rounded-lg border border-space-800">
                  <span className="font-pixel text-[10px] text-cosmic-amber block mb-1">
                    INPUT FORMAT:
                  </span>
                  <p className="text-slate-300">{problem.inputFormat}</p>
                </div>

                <div className="bg-space-950/70 p-3 rounded-lg border border-space-800">
                  <span className="font-pixel text-[10px] text-cosmic-amber block mb-1">
                    OUTPUT FORMAT:
                  </span>
                  <p className="text-slate-300 whitespace-pre-wrap">{problem.outputFormat}</p>
                </div>

                <div className="bg-space-950/70 p-3 rounded-lg border border-space-800">
                  <span className="font-pixel text-[10px] text-cosmic-orange block mb-1">
                    CONSTRAINTS:
                  </span>
                  <p className="text-slate-300 font-mono text-[11px] whitespace-pre-wrap">{problem.constraints}</p>
                </div>
              </div>

              {/* Sample I/O */}
              <div className="space-y-2 pt-2">
                <h3 className="font-pixel text-[11px] text-cosmic-cyan tracking-wider">
                  SAMPLE TELEMETRY
                </h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div className="bg-space-950 p-2.5 rounded border border-space-800">
                    <span className="text-[10px] text-slate-400 block mb-1 font-pixel">SAMPLE INPUT</span>
                    <pre className="font-mono text-cosmic-cyan text-[11px] whitespace-pre-wrap">{problem.sampleInput}</pre>
                  </div>
                  <div className="bg-space-950 p-2.5 rounded border border-space-800">
                    <span className="text-[10px] text-slate-400 block mb-1 font-pixel">SAMPLE OUTPUT</span>
                    <pre className="font-mono text-cosmic-emerald text-[11px] whitespace-pre-wrap">{problem.sampleOutput}</pre>
                  </div>
                </div>
              </div>
            </>
          ) : (
            /* Tiered Hint System Panel */
            <div className="space-y-4">
              <div className="flex items-center gap-3 bg-space-850 p-3 rounded-lg border border-space-700">
                <img 
                  src="/sprites/astronaut_hint.png" 
                  alt="Confused Astronaut" 
                  className="w-12 h-12 object-contain pixelated" 
                />
                <div>
                  <h4 className="font-pixel text-[10px] text-cosmic-amber">TIERED FLIGHT ASSISTANCE</h4>
                  <p className="text-[11px] text-slate-400 mt-0.5">
                    Hints provide progressive algorithmic clues. Unlocking costs XP!
                  </p>
                </div>
              </div>

              {problem.hints.map((hint) => {
                const isUnlocked = unlockedHintLevels.includes(hint.level);
                return (
                  <div 
                    key={hint.level}
                    className={`p-3.5 rounded-lg border transition-all ${
                      isUnlocked 
                        ? 'bg-space-850 border-cosmic-amber/50' 
                        : 'bg-space-950 border-space-800'
                    }`}
                  >
                    <div className="flex items-center justify-between mb-2">
                      <span className="font-pixel text-[10px] text-slate-300">
                        HINT LEVEL #{hint.level}
                      </span>
                      {!isUnlocked ? (
                        <button
                          onClick={() => {
                            soundFx.playClick();
                            handleUnlockHint(hint);
                          }}
                          className="flex items-center gap-1 px-2.5 py-1 rounded bg-cosmic-orange/20 border border-cosmic-orange text-cosmic-orange text-[10px] font-pixel hover:bg-cosmic-orange hover:text-space-950 transition-colors"
                        >
                          <Zap className="w-3 h-3" />
                          <span>UNLOCK (-{hint.cost} XP)</span>
                        </button>
                      ) : (
                        <span className="text-[10px] font-pixel text-cosmic-emerald">
                          UNLOCKED
                        </span>
                      )}
                    </div>

                    {isUnlocked ? (
                      <p className="text-slate-200 leading-relaxed font-retro text-xs">
                        {hint.text}
                      </p>
                    ) : (
                      <div className="h-10 bg-space-900/50 rounded flex items-center justify-center text-slate-500 text-[11px] italic">
                        Encrypted telemetry transmission. Unlock to reveal.
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* ================= DRAGGABLE SPLIT HANDLE with Golden Ratio Snaps ================= */}
      <div
        onPointerDown={handlePointerDown}
        className="group relative w-full md:w-2 h-2 md:h-full bg-space-900 hover:bg-cosmic-cyan/60 active:bg-cosmic-cyan flex items-center justify-center cursor-row-resize md:cursor-col-resize transition-colors z-20"
        title="Drag to resize panels (Adheres to Golden Ratio)"
      >
        <div className="hidden md:flex flex-col items-center gap-1 py-2">
          <div className="w-1 h-3 rounded-full bg-slate-500 group-hover:bg-space-950" />
          <div className="w-1 h-3 rounded-full bg-slate-500 group-hover:bg-space-950" />
        </div>

        {/* Quick Snap Floating Menu */}
        <div className="absolute top-2 left-1/2 -translate-x-1/2 hidden group-hover:flex items-center gap-1 bg-space-950 border border-cosmic-cyan/50 px-2 py-1 rounded-md text-[9px] font-pixel text-cosmic-cyan whitespace-nowrap shadow-xl z-30">
          <button 
            onClick={(e) => { e.stopPropagation(); snapToGoldenRatio(); }}
            className="hover:underline hover:text-white"
          >
            φ SNAP (38.2%)
          </button>
          <span>|</span>
          <button 
            onClick={(e) => { e.stopPropagation(); snapToEqual(); }}
            className="hover:underline hover:text-white"
          >
            50%
          </button>
        </div>
      </div>

      {/* ================= RIGHT PANE: Code Editor & Execution Deck (Golden Ratio ~61.8%) ================= */}
      <div 
        style={{ width: `${100 - splitRatio}%` }}
        className="h-full flex flex-col bg-space-950 overflow-hidden"
      >
        {/* Editor Action Bar (SRS Section 3.4) */}
        <div className="h-14 px-4 bg-space-950/90 border-b border-space-800 flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <FileCode className="w-4 h-4 text-cosmic-orange" />
            <span className="text-xs font-mono text-slate-300 hidden sm:inline">
              main.c (GCC 14 C17)
            </span>
          </div>

          {/* Action Buttons: Hint, Reset, Run Sample, Submit */}
          <div className="flex items-center gap-2">
            {/* Hint Button */}
            <button
              onClick={() => {
                soundFx.playClick();
                setActiveTab('hints');
              }}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-space-850 hover:bg-space-800 border border-space-700 text-xs font-retro text-cosmic-amber transition-colors"
              title="Need assistance? Access tiered hints"
            >
              <HelpCircle className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">HINT</span>
            </button>

            {/* Reset Code Button */}
            <button
              onClick={() => {
                soundFx.playClick();
                if (confirm('Reset code to starter template?')) {
                  setCode(problem.starterCode);
                }
              }}
              className="p-1.5 rounded bg-space-850 hover:bg-space-800 border border-space-700 text-slate-400 hover:text-slate-200 transition-colors"
              title="Reset Code Template"
            >
              <RotateCcw className="w-3.5 h-3.5" />
            </button>

            {/* Run Sample Tests */}
            <button
              disabled={isEvaluating}
              onClick={() => handleExecute(false)}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-space-800 hover:bg-space-700 border border-space-600 text-xs font-retro text-slate-200 transition-colors disabled:opacity-50"
            >
              <Play className="w-3.5 h-3.5 text-cosmic-cyan" />
              <span className="hidden sm:inline">RUN TEST</span>
            </button>

            {/* Submit Solution Button (Cosmic Glow Aura) */}
            <button
              disabled={isEvaluating}
              onClick={() => handleExecute(true)}
              className="flex items-center gap-1.5 px-4 py-1.5 rounded bg-cosmic-orange hover:bg-orange-500 text-space-950 text-xs font-pixel font-bold shadow-glow-orange transition-all duration-200 disabled:opacity-50"
            >
              <Send className="w-3.5 h-3.5" />
              <span>{isEvaluating ? 'COMPILING...' : 'SUBMIT'}</span>
            </button>
          </div>
        </div>

        {/* Monaco Code Editor Area */}
        <div className="flex-1 relative overflow-hidden bg-space-950">
          <Editor
            height="100%"
            defaultLanguage="c"
            language="c"
            theme="vs-dark"
            value={code}
            onChange={(val) => {
              setCode(val || '');
              soundFx.playType();
            }}
            options={{
              fontSize: 14,
              fontFamily: "'Fira Code', 'JetBrains Mono', Consolas, monospace",
              fontLigatures: true,
              minimap: { enabled: false },
              scrollBeyondLastLine: false,
              automaticLayout: true,
              tabSize: 4,
              insertSpaces: true,
              renderLineHighlight: 'all',
              bracketPairColorization: { enabled: true },
              lineNumbers: 'on',
              padding: { top: 12, bottom: 12 }
            }}
          />
        </div>

        {/* Lower Test Execution Console / Terminal Split Panel */}
        <div className="h-64 border-t border-space-800 bg-space-900/90 backdrop-blur-md flex flex-col">
          {/* Console Header Bar */}
          <div className="h-10 px-4 bg-space-950 border-b border-space-800 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-1.5">
                <Terminal className="w-4 h-4 text-cosmic-cyan" />
                <span className="text-xs font-pixel text-slate-200">
                  EXECUTION TELEMETRY
                </span>
              </div>

              {/* Status Badge */}
              {evalResult && (
                <span className={`text-[10px] font-pixel px-2 py-0.5 rounded ${
                  evalResult.allPassed 
                    ? 'bg-cosmic-emerald/20 text-cosmic-emerald border border-cosmic-emerald'
                    : 'bg-rose-950 text-rose-400 border border-rose-800'
                }`}>
                  {evalResult.allPassed ? 'ALL TEST CASES PASSED' : 'TESTS FAILED'}
                </span>
              )}
            </div>

            {/* Astronaut Live Reaction Avatar */}
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-retro text-slate-400 hidden sm:inline">
                {isEvaluating ? 'Compiling in isolated sandbox...' : 'Engine Ready'}
              </span>
              <img 
                src={astronautReaction} 
                alt="Astronaut Reaction" 
                className="w-8 h-8 object-contain pixelated" 
              />
            </div>
          </div>

          {/* Console Content: Test Cases Cards */}
          <div className="flex-1 overflow-y-auto p-3 text-xs font-mono">
            {evalResult ? (
              evalResult.compilationError ? (
                /* Compilation Error View */
                <div className="p-3 bg-red-950/40 border border-red-800/80 rounded-lg text-red-300 space-y-1">
                  <div className="flex items-center gap-2 font-pixel text-[11px] text-red-400">
                    <AlertTriangle className="w-4 h-4" />
                    <span>COMPILATION / SYNTAX ERROR</span>
                  </div>
                  <pre className="text-xs whitespace-pre-wrap">{evalResult.compilationError}</pre>
                </div>
              ) : (
                /* Test Case Tabs & Output Inspector */
                <div className="space-y-3">
                  {/* Test Case Selectors */}
                  <div className="flex items-center gap-2 overflow-x-auto pb-1">
                    {evalResult.results.map((tc, idx) => (
                      <button
                        key={tc.id}
                        onClick={() => {
                          soundFx.playClick();
                          setSelectedTestCaseIdx(idx);
                        }}
                        className={`flex items-center gap-1.5 px-3 py-1.5 rounded border text-xs font-retro transition-colors ${
                          selectedTestCaseIdx === idx
                            ? 'bg-space-800 border-cosmic-cyan text-cosmic-cyan'
                            : 'bg-space-950 border-space-800 text-slate-400 hover:text-slate-200'
                        }`}
                      >
                        {tc.passed ? (
                          <CheckCircle className="w-3.5 h-3.5 text-cosmic-emerald" />
                        ) : (
                          <XCircle className="w-3.5 h-3.5 text-rose-500" />
                        )}
                        <span>{tc.desc}</span>
                        {tc.hidden && (
                          <span className="text-[9px] px-1 rounded bg-space-900 text-slate-500">
                            HIDDEN
                          </span>
                        )}
                      </button>
                    ))}
                  </div>

                  {/* Selected Test Case Inspection */}
                  {evalResult.results[selectedTestCaseIdx] && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-3 bg-space-950 p-3 rounded-lg border border-space-800">
                      <div>
                        <span className="text-[10px] font-pixel text-slate-400 block mb-1">
                          STDIN INPUT
                        </span>
                        <pre className="bg-space-900 p-2 rounded text-slate-300 whitespace-pre-wrap">
                          {evalResult.results[selectedTestCaseIdx].input}
                        </pre>
                      </div>

                      <div>
                        <span className="text-[10px] font-pixel text-slate-400 block mb-1">
                          EXPECTED STDOUT
                        </span>
                        <pre className="bg-space-900 p-2 rounded text-cosmic-emerald whitespace-pre-wrap">
                          {evalResult.results[selectedTestCaseIdx].expectedOutput}
                        </pre>
                      </div>

                      <div>
                        <span className="text-[10px] font-pixel text-slate-400 block mb-1">
                          YOUR PROGRAM STDOUT
                        </span>
                        <pre className={`p-2 rounded whitespace-pre-wrap ${
                          evalResult.results[selectedTestCaseIdx].passed
                            ? 'bg-space-900 text-cosmic-emerald'
                            : 'bg-red-950/40 text-red-300 border border-red-800/50'
                        }`}>
                          {evalResult.results[selectedTestCaseIdx].actualOutput}
                        </pre>
                      </div>
                    </div>
                  )}
                </div>
              )
            ) : (
              /* Idle Terminal Message */
              <div className="h-full flex flex-col items-center justify-center text-slate-500 font-retro space-y-1">
                <span>Isolated C Sandbox idle.</span>
                <span className="text-[11px]">Click [SUBMIT] or [RUN TEST] to evaluate your solution.</span>
              </div>
            )}
          </div>
        </div>

      </div>

    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import Editor from '@monaco-editor/react';
import confetti from 'canvas-confetti';
import { 
  Play, 
  Send, 
  HelpCircle, 
  RotateCcw, 
  CheckCircle, 
  XCircle, 
  Terminal, 
  FileCode,
  Zap,
  AlertTriangle,
  ArrowLeft
} from 'lucide-react';
import { soundFx } from '../services/soundFx';
import { cEngine } from '../services/cEngine';

export default function Workspace({ 
  problem, 
  userProgress, 
  onProblemSolved, 
  onBackToMap,
  onDeductXp
}) {
  const [code, setCode] = useState(problem.starterCode);
  const [splitRatio, setSplitRatio] = useState(38.2); // Golden Ratio default
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState('problem'); // 'problem' | 'hints'
  const [isMobileTab, setIsMobileTab] = useState('editor'); // 'spec' | 'editor' on mobile

  // Execution status
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [evalResult, setEvalResult] = useState(null);
  const [selectedTestCaseIdx, setSelectedTestCaseIdx] = useState(0);
  const [astronautReaction, setAstronautReaction] = useState('/sprites/astronaut_floating.png');

  // Hint management
  const [unlockedHintLevels, setUnlockedHintLevels] = useState([]);

  const containerRef = useRef(null);

  // Sync state when problem changes
  useEffect(() => {
    setCode(problem.starterCode);
    setEvalResult(null);
    setSelectedTestCaseIdx(0);
    setAstronautReaction('/sprites/astronaut_floating.png');
    setUnlockedHintLevels([]);
  }, [problem.id]);

  // Handle Dragging Split-Pane Handle with 60fps pointer events
  const handlePointerDown = (e) => {
    e.preventDefault();
    setIsDragging(true);
    soundFx.playClick();
  };

  useEffect(() => {
    const handlePointerMove = (e) => {
      if (!isDragging || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const pointerX = e.clientX - rect.left;
      const newRatio = (pointerX / rect.width) * 100;
      if (newRatio >= 22 && newRatio <= 78) {
        setSplitRatio(newRatio);
      }
    };

    const handlePointerUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    if (isDragging) {
      window.addEventListener('pointermove', handlePointerMove);
      window.addEventListener('pointerup', handlePointerUp);
    }
    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [isDragging]);

  const snapToGoldenRatio = () => {
    soundFx.playClick();
    setSplitRatio(38.2);
  };

  const snapToEqual = () => {
    soundFx.playClick();
    setSplitRatio(50);
  };

  // Run Code / Submit Code
  const handleExecute = async (isSubmission = true) => {
    soundFx.playCompile();
    setIsEvaluating(true);
    setAstronautReaction('/sprites/astronaut_typing.png');

    try {
      const res = await cEngine.evaluateSubmission(problem, code);
      setIsEvaluating(false);
      setEvalResult(res);

      if (res.allPassed) {
        soundFx.playPass();
        soundFx.playLevelUp();
        setAstronautReaction('/sprites/astronaut_cheering.png');

        confetti({
          particleCount: 90,
          spread: 60,
          origin: { y: 0.6 }
        });

        if (isSubmission) {
          onProblemSolved(problem.id, res.earnedXp);
        }
      } else {
        soundFx.playFail();
        setAstronautReaction('/sprites/astronaut_hint.png');
      }
    } catch (err) {
      setIsEvaluating(false);
      soundFx.playFail();
      setAstronautReaction('/sprites/astronaut_hint.png');
      setEvalResult({
        allPassed: false,
        compilationError: err.message,
        results: []
      });
    }
  };

  const handleUnlockHint = (hint) => {
    if (unlockedHintLevels.includes(hint.level)) return;
    if (userProgress.xp < hint.cost) {
      soundFx.playFail();
      alert(`Insufficient XP! You need ${hint.cost} XP to unlock this hint.`);
      return;
    }
    soundFx.playWarp();
    onDeductXp(hint.cost);
    setUnlockedHintLevels([...unlockedHintLevels, hint.level]);
  };

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-[calc(100vh-4rem)] flex flex-col md:flex-row overflow-hidden bg-charcoal-950 select-none ${
        isDragging ? 'cursor-col-resize' : ''
      }`}
    >
      {/* Mobile Top View Switcher (Visible only on small screens) */}
      <div className="flex md:hidden items-center justify-between bg-charcoal-900 border-b border-charcoal-750 px-3 py-2 text-xs font-retro">
        <button
          onClick={onBackToMap}
          className="flex items-center gap-1 text-slate-400 hover:text-white"
        >
          <ArrowLeft className="w-3.5 h-3.5" />
          <span>MAP</span>
        </button>

        <div className="flex items-center gap-1 bg-charcoal-950 p-1 rounded-lg border border-charcoal-800">
          <button
            onClick={() => setIsMobileTab('spec')}
            className={`px-3 py-1 rounded text-[10px] font-pixel ${isMobileTab === 'spec' ? 'bg-cosmic-cyan text-charcoal-950 font-bold' : 'text-slate-400'}`}
          >
            PROBLEM
          </button>
          <button
            onClick={() => setIsMobileTab('editor')}
            className={`px-3 py-1 rounded text-[10px] font-pixel ${isMobileTab === 'editor' ? 'bg-cosmic-orange text-charcoal-950 font-bold' : 'text-slate-400'}`}
          >
            CODE & TEST
          </button>
        </div>
      </div>

      {/* ================= LEFT PANE: Problem Statement Panel ================= */}
      <div 
        style={{ width: `${splitRatio}%` }}
        className={`h-full flex-col border-r border-charcoal-750 bg-charcoal-900/95 overflow-hidden ${
          isMobileTab === 'spec' ? 'flex w-full md:w-auto' : 'hidden md:flex'
        }`}
      >
        {/* Panel Header */}
        <div className="h-12 px-4 bg-charcoal-950 border-b border-charcoal-750 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-cosmic-cyan animate-pulse" />
            <h2 className="text-xs font-pixel text-slate-100 truncate max-w-[200px] sm:max-w-[260px]">
              {problem.title}
            </h2>
          </div>
          <span className="text-[10px] font-retro px-2 py-0.5 rounded bg-cosmic-orange/20 border border-cosmic-orange text-cosmic-orange">
            +{problem.xpReward} XP
          </span>
        </div>

        {/* Tab Switcher: Problem Briefing / Hints */}
        <div className="flex items-center border-b border-charcoal-750 bg-charcoal-900 text-xs font-retro">
          <button
            onClick={() => { soundFx.playClick(); setActiveTab('problem'); }}
            className={`flex-1 py-2 text-center transition-colors ${
              activeTab === 'problem'
                ? 'border-b-2 border-cosmic-cyan text-cosmic-cyan font-bold bg-charcoal-850'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            BRIEFING & SPECS
          </button>
          <button
            onClick={() => { soundFx.playClick(); setActiveTab('hints'); }}
            className={`flex-1 py-2 text-center transition-colors flex items-center justify-center gap-1.5 ${
              activeTab === 'hints'
                ? 'border-b-2 border-cosmic-amber text-cosmic-amber font-bold bg-charcoal-850'
                : 'text-slate-400 hover:text-slate-200'
            }`}
          >
            <HelpCircle className="w-3.5 h-3.5" />
            <span>HINTS ({unlockedHintLevels.length}/{problem.hints.length})</span>
          </button>
        </div>

        {/* Panel Body: Scrollable Content with smooth charcoal scroll */}
        <div className="flex-1 overflow-y-auto p-4 text-xs text-slate-300 font-retro space-y-4">
          {activeTab === 'problem' ? (
            <>
              <div className="flex items-center justify-between bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                <span className="text-slate-400">SYLLABUS REF:</span>
                <span className="text-cosmic-cyan font-semibold">{problem.syllabusRef}</span>
              </div>

              <div className="space-y-2">
                <h3 className="font-pixel text-[10px] text-cosmic-cyan tracking-wider">
                  MISSION OBJECTIVE
                </h3>
                <p className="leading-relaxed whitespace-pre-wrap text-slate-200">
                  {problem.description}
                </p>
              </div>

              <div className="space-y-2.5">
                <div className="bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                  <span className="font-pixel text-[9px] text-cosmic-amber block mb-1">
                    INPUT FORMAT:
                  </span>
                  <p className="text-slate-300">{problem.inputFormat}</p>
                </div>

                <div className="bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                  <span className="font-pixel text-[9px] text-cosmic-amber block mb-1">
                    OUTPUT FORMAT:
                  </span>
                  <p className="text-slate-300 whitespace-pre-wrap">{problem.outputFormat}</p>
                </div>

                <div className="bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                  <span className="font-pixel text-[9px] text-cosmic-orange block mb-1">
                    CONSTRAINTS:
                  </span>
                  <p className="text-slate-300 font-mono text-[11px] whitespace-pre-wrap">{problem.constraints}</p>
                </div>
              </div>

              {/* Sample I/O */}
              <div className="space-y-2">
                <h3 className="font-pixel text-[10px] text-cosmic-cyan tracking-wider">
                  SAMPLE TELEMETRY
                </h3>
                <div className="grid grid-cols-1 gap-2.5">
                  <div className="bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                    <span className="text-[9px] text-slate-400 block mb-1 font-pixel">SAMPLE INPUT</span>
                    <pre className="font-mono text-cosmic-cyan text-[11px] whitespace-pre-wrap">{problem.sampleInput}</pre>
                  </div>
                  <div className="bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                    <span className="text-[9px] text-slate-400 block mb-1 font-pixel">SAMPLE OUTPUT</span>
                    <pre className="font-mono text-cosmic-emerald text-[11px] whitespace-pre-wrap">{problem.sampleOutput}</pre>
                  </div>
                </div>
              </div>
            </>
          ) : (
            /* Tiered Hint System */
            <div className="space-y-3">
              <div className="flex items-center gap-3 bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                <img 
                  src="/sprites/astronaut_hint.png" 
                  alt="Hint" 
                  style={{ width: '40px', height: '40px', maxWidth: '40px', maxHeight: '40px' }}
                  className="object-contain pixelated" 
                />
                <div>
                  <h4 className="font-pixel text-[10px] text-cosmic-amber">TIERED HINT TRANSMISSION</h4>
                  <p className="text-[11px] text-slate-400 mt-0.5">
                    Hints provide algorithmic assistance at the cost of XP.
                  </p>
                </div>
              </div>

              {problem.hints.map((hint) => {
                const isUnlocked = unlockedHintLevels.includes(hint.level);
                return (
                  <div 
                    key={hint.level}
                    className={`p-3 rounded-xl border transition-all ${
                      isUnlocked ? 'bg-charcoal-850 border-cosmic-amber/50' : 'bg-charcoal-950 border-charcoal-800'
                    }`}
                  >
                    <div className="flex items-center justify-between mb-2">
                      <span className="font-pixel text-[10px] text-slate-300">
                        HINT LEVEL #{hint.level}
                      </span>
                      {!isUnlocked ? (
                        <button
                          onClick={() => handleUnlockHint(hint)}
                          className="flex items-center gap-1 px-2.5 py-1 rounded bg-cosmic-orange/20 border border-cosmic-orange text-cosmic-orange text-[9px] font-pixel hover:bg-cosmic-orange hover:text-charcoal-950 transition-colors"
                        >
                          <Zap className="w-3 h-3" />
                          <span>UNLOCK (-{hint.cost} XP)</span>
                        </button>
                      ) : (
                        <span className="text-[9px] font-pixel text-cosmic-emerald">
                          UNLOCKED
                        </span>
                      )}
                    </div>

                    {isUnlocked ? (
                      <p className="text-slate-200 leading-relaxed font-retro text-xs">
                        {hint.text}
                      </p>
                    ) : (
                      <div className="h-8 bg-charcoal-900/60 rounded flex items-center justify-center text-slate-500 text-[10px] italic">
                        Encrypted hint transmission.
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* ================= DRAGGABLE SPLIT HANDLE ================= */}
      <div
        onPointerDown={handlePointerDown}
        className="hidden md:flex relative w-2 h-full bg-charcoal-900 hover:bg-cosmic-cyan/50 active:bg-cosmic-cyan items-center justify-center cursor-col-resize transition-colors z-20 group"
        title="Drag to resize (φ snap)"
      >
        <div className="flex flex-col items-center gap-1">
          <div className="w-0.5 h-3 rounded bg-slate-600 group-hover:bg-charcoal-950" />
          <div className="w-0.5 h-3 rounded bg-slate-600 group-hover:bg-charcoal-950" />
        </div>

        <div className="absolute top-2 left-1/2 -translate-x-1/2 hidden group-hover:flex items-center gap-1 bg-charcoal-950 border border-cosmic-cyan px-2 py-0.5 rounded text-[8px] font-pixel text-cosmic-cyan whitespace-nowrap shadow-xl z-30">
          <button onClick={(e) => { e.stopPropagation(); snapToGoldenRatio(); }} className="hover:underline">
            φ (38.2%)
          </button>
          <span>|</span>
          <button onClick={(e) => { e.stopPropagation(); snapToEqual(); }} className="hover:underline">
            50%
          </button>
        </div>
      </div>

      {/* ================= RIGHT PANE: Code Editor & Console ================= */}
      <div 
        style={{ width: `${100 - splitRatio}%` }}
        className={`h-full flex-col bg-charcoal-950 overflow-hidden ${
          isMobileTab === 'editor' ? 'flex w-full md:w-auto' : 'hidden md:flex'
        }`}
      >
        {/* Editor Action Bar */}
        <div className="h-12 px-3 sm:px-4 bg-charcoal-950 border-b border-charcoal-750 flex items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <FileCode className="w-4 h-4 text-cosmic-orange" />
            <span className="text-xs font-mono text-slate-300">
              main.c (C17 / GCC)
            </span>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={() => { soundFx.playClick(); setActiveTab('hints'); setIsMobileTab('spec'); }}
              className="flex items-center gap-1 px-2.5 py-1 rounded bg-charcoal-900 hover:bg-charcoal-850 border border-charcoal-750 text-xs font-retro text-cosmic-amber transition-colors"
            >
              <HelpCircle className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">HINT</span>
            </button>

            <button
              onClick={() => {
                soundFx.playClick();
                if (confirm('Reset to starter C code?')) setCode(problem.starterCode);
              }}
              className="p-1 rounded bg-charcoal-900 hover:bg-charcoal-850 border border-charcoal-750 text-slate-400 hover:text-slate-200 transition-colors"
              title="Reset Code Template"
            >
              <RotateCcw className="w-3.5 h-3.5" />
            </button>

            <button
              disabled={isEvaluating}
              onClick={() => handleExecute(false)}
              className="flex items-center gap-1.5 px-3 py-1 rounded bg-charcoal-850 hover:bg-charcoal-800 border border-charcoal-700 text-xs font-retro text-slate-200 transition-colors disabled:opacity-50"
            >
              <Play className="w-3.5 h-3.5 text-cosmic-cyan" />
              <span>TEST</span>
            </button>

            <button
              disabled={isEvaluating}
              onClick={() => handleExecute(true)}
              className="flex items-center gap-1.5 px-3.5 py-1 rounded bg-cosmic-orange hover:bg-orange-500 text-charcoal-950 text-xs font-pixel font-bold shadow-glow-orange transition-all disabled:opacity-50"
            >
              <Send className="w-3.5 h-3.5" />
              <span>{isEvaluating ? 'RUNNING' : 'SUBMIT'}</span>
            </button>
          </div>
        </div>

        {/* Monaco Editor Container */}
        <div className="flex-1 relative overflow-hidden bg-charcoal-950 min-h-[220px]">
          <Editor
            height="100%"
            defaultLanguage="c"
            language="c"
            theme="vs-dark"
            value={code}
            onChange={(val) => {
              setCode(val || '');
              soundFx.playType();
            }}
            options={{
              fontSize: 13,
              fontFamily: "'Fira Code', 'JetBrains Mono', Consolas, monospace",
              minimap: { enabled: false },
              scrollBeyondLastLine: false,
              automaticLayout: true,
              tabSize: 4,
              insertSpaces: true,
              lineNumbers: 'on',
              padding: { top: 8, bottom: 8 }
            }}
          />
        </div>

        {/* Lower Test Execution Console */}
        <div className="h-56 border-t border-charcoal-750 bg-charcoal-900/98 flex flex-col">
          {/* Console Header */}
          <div className="h-9 px-4 bg-charcoal-950 border-b border-charcoal-750 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Terminal className="w-3.5 h-3.5 text-cosmic-cyan" />
              <span className="text-[11px] font-pixel text-slate-200">
                EVALUATION CONSOLE
              </span>
              {evalResult && (
                <span className={`text-[9px] font-pixel px-1.5 py-0.2 rounded ml-2 ${
                  evalResult.allPassed 
                    ? 'bg-cosmic-emerald/20 text-cosmic-emerald border border-cosmic-emerald/50'
                    : 'bg-red-950/60 text-red-400 border border-red-800/60'
                }`}>
                  {evalResult.allPassed ? 'PASSED' : 'FAILED'}
                </span>
              )}
            </div>

            {/* Strictly constrained reaction avatar */}
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-retro text-slate-400 hidden sm:inline">
                {isEvaluating ? 'Sandbox Compiling...' : 'Ready'}
              </span>
              <img 
                src={astronautReaction} 
                alt="Reaction" 
                style={{ width: '28px', height: '28px', maxWidth: '28px', maxHeight: '28px' }}
                className="object-contain pixelated" 
              />
            </div>
          </div>

          {/* Test Case Breakdown */}
          <div className="flex-1 overflow-y-auto p-3 text-xs font-mono">
            {evalResult ? (
              evalResult.compilationError ? (
                <div className="p-2.5 bg-red-950/40 border border-red-800/60 rounded-xl text-red-300 space-y-1">
                  <div className="flex items-center gap-1.5 font-pixel text-[10px] text-red-400">
                    <AlertTriangle className="w-3.5 h-3.5" />
                    <span>SYNTAX / COMPILATION ERROR</span>
                  </div>
                  <pre className="text-xs whitespace-pre-wrap">{evalResult.compilationError}</pre>
                </div>
              ) : (
                <div className="space-y-2.5">
                  <div className="flex items-center gap-1.5 overflow-x-auto pb-0.5">
                    {evalResult.results.map((tc, idx) => (
                      <button
                        key={tc.id}
                        onClick={() => { soundFx.playClick(); setSelectedTestCaseIdx(idx); }}
                        className={`flex items-center gap-1 px-2.5 py-1 rounded-lg border text-xs font-retro transition-colors ${
                          selectedTestCaseIdx === idx
                            ? 'bg-charcoal-800 border-cosmic-cyan text-cosmic-cyan'
                            : 'bg-charcoal-950 border-charcoal-800 text-slate-400'
                        }`}
                      >
                        {tc.passed ? (
                          <CheckCircle className="w-3 h-3 text-cosmic-emerald" />
                        ) : (
                          <XCircle className="w-3 h-3 text-rose-500" />
                        )}
                        <span>{tc.desc}</span>
                      </button>
                    ))}
                  </div>

                  {evalResult.results[selectedTestCaseIdx] && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-2.5 bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                      <div>
                        <span className="text-[9px] font-pixel text-slate-400 block mb-0.5">INPUT</span>
                        <pre className="bg-charcoal-900 p-1.5 rounded text-slate-300 whitespace-pre-wrap text-[11px]">
                          {evalResult.results[selectedTestCaseIdx].input}
                        </pre>
                      </div>

                      <div>
                        <span className="text-[9px] font-pixel text-slate-400 block mb-0.5">EXPECTED OUTPUT</span>
                        <pre className="bg-charcoal-900 p-1.5 rounded text-cosmic-emerald whitespace-pre-wrap text-[11px]">
                          {evalResult.results[selectedTestCaseIdx].expectedOutput}
                        </pre>
                      </div>

                      <div>
                        <span className="text-[9px] font-pixel text-slate-400 block mb-0.5">YOUR OUTPUT</span>
                        <pre className={`p-1.5 rounded whitespace-pre-wrap text-[11px] ${
                          evalResult.results[selectedTestCaseIdx].passed
                            ? 'bg-charcoal-900 text-cosmic-emerald'
                            : 'bg-red-950/40 text-red-300 border border-red-800/50'
                        }`}>
                          {evalResult.results[selectedTestCaseIdx].actualOutput}
                        </pre>
                      </div>
                    </div>
                  )}
                </div>
              )
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-500 font-retro">
                <span className="text-[11px]">Ready to evaluate. Press [SUBMIT] or [TEST].</span>
              </div>
            )}
          </div>
        </div>

      </div>

    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import Editor from '@monaco-editor/react';
import confetti from 'canvas-confetti';
import { 
  Play, 
  Send, 
  HelpCircle, 
  RotateCcw, 
  CheckCircle, 
  XCircle, 
  Terminal, 
  FileCode,
  Zap,
  AlertTriangle,
  ArrowLeft,
  ChevronLeft,
  ChevronRight,
  Sparkles,
  CheckCircle2
} from 'lucide-react';
import { soundFx } from '../services/soundFx';
import { cEngine } from '../services/cEngine';
import { PROBLEMS } from '../data/curriculum';

export default function Workspace({ 
  problem, 
  userProgress, 
  onProblemSolved, 
  onBackToMap,
  onDeductXp,
  onNextProblem,
  onPrevProblem,
  hasNextProblem,
  hasPrevProblem,
  problemIndex,
  totalProblems
}) {
  const [code, setCode] = useState(problem.starterCode);
  const [splitRatio, setSplitRatio] = useState(38.2); // Golden Ratio default
  const [isDragging, setIsDragging] = useState(false);
  const [activeTab, setActiveTab] = useState('problem'); // 'problem' | 'hints'
  const [isMobileTab, setIsMobileTab] = useState('editor'); // 'spec' | 'editor' on mobile

  // Execution status
  const [isEvaluating, setIsEvaluating] = useState(false);
  const [evalResult, setEvalResult] = useState(null);
  const [selectedTestCaseIdx, setSelectedTestCaseIdx] = useState(0);
  const [astronautReaction, setAstronautReaction] = useState('/sprites/astronaut_floating.png');

  // Hint management
  const [unlockedHintLevels, setUnlockedHintLevels] = useState([]);

  const containerRef = useRef(null);

  const isCurrentCleared = userProgress.clearedProblems.includes(problem.id);

  // Sync state when problem changes
  useEffect(() => {
    setCode(problem.starterCode);
    setEvalResult(null);
    setSelectedTestCaseIdx(0);
    setAstronautReaction('/sprites/astronaut_floating.png');
    setUnlockedHintLevels([]);
  }, [problem.id]);

  // Handle Dragging Split-Pane Handle with 60fps pointer events
  const handlePointerDown = (e) => {
    e.preventDefault();
    setIsDragging(true);
    soundFx.playClick();
  };

  useEffect(() => {
    const handlePointerMove = (e) => {
      if (!isDragging || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const pointerX = e.clientX - rect.left;
      const newRatio = (pointerX / rect.width) * 100;
      if (newRatio >= 22 && newRatio <= 78) {
        setSplitRatio(newRatio);
      }
    };

    const handlePointerUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    if (isDragging) {
      window.addEventListener('pointermove', handlePointerMove);
      window.addEventListener('pointerup', handlePointerUp);
    }
    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [isDragging]);

  const snapToGoldenRatio = () => {
    soundFx.playClick();
    setSplitRatio(38.2);
  };

  const snapToEqual = () => {
    soundFx.playClick();
    setSplitRatio(50);
  };

  // Run Code / Submit Code
  const handleExecute = async (isSubmission = true) => {
    soundFx.playCompile();
    setIsEvaluating(true);
    setAstronautReaction('/sprites/astronaut_typing.png');

    try {
      const res = await cEngine.evaluateSubmission(problem, code);
      setIsEvaluating(false);
      setEvalResult(res);

      if (res.allPassed) {
        soundFx.playPass();
        soundFx.playLevelUp();
        setAstronautReaction('/sprites/astronaut_cheering.png');

        confetti({
          particleCount: 90,
          spread: 60,
          origin: { y: 0.6 }
        });

        if (isSubmission) {
          onProblemSolved(problem.id, res.earnedXp);
        }
      } else {
        soundFx.playFail();
        setAstronautReaction('/sprites/astronaut_hint.png');
      }
    } catch (err) {
      setIsEvaluating(false);
      soundFx.playFail();
      setAstronautReaction('/sprites/astronaut_hint.png');
      setEvalResult({
        allPassed: false,
        compilationError: err.message,
        results: []
      });
    }
  };

  const handleUnlockHint = (hint) => {
    if (unlockedHintLevels.includes(hint.level)) return;
    if (userProgress.xp < hint.cost) {
      soundFx.playFail();
      alert(`Insufficient XP! You need ${hint.cost} XP to unlock this hint.`);
      return;
    }
    soundFx.playWarp();
    onDeductXp(hint.cost);
    setUnlockedHintLevels([...unlockedHintLevels, hint.level]);
  };

  return (
    <div className="relative w-full h-[calc(100vh-4rem)] flex flex-col overflow-hidden bg-charcoal-950 select-none">

      {/* ================= TOP NAVIGATION BAR: Next Problem Bar (Same CSS Style) ================= */}
      <div className="h-11 px-3 sm:px-6 bg-charcoal-900 border-b border-charcoal-750 flex items-center justify-between gap-3 text-xs font-retro z-20">

        {/* Previous Problem Button */}
        <button
          onClick={() => {
            if (hasPrevProblem) {
              soundFx.playClick();
              onPrevProblem();
            }
          }}
          disabled={!hasPrevProblem}
          className="flex items-center gap-1 px-3 py-1 rounded-lg bg-charcoal-950 border border-charcoal-750 text-slate-300 hover:text-white hover:border-cosmic-cyan disabled:opacity-30 disabled:pointer-events-none transition-colors"
        >
          <ChevronLeft className="w-3.5 h-3.5 text-cosmic-cyan" />
          <span className="hidden sm:inline">PREV LAB</span>
        </button>

        {/* Center Progress Mission Indicator */}
        <div className="flex items-center gap-2 truncate text-center">
          <button 
            onClick={onBackToMap}
            className="hidden md:flex items-center gap-1 text-[11px] text-slate-400 hover:text-cosmic-cyan border-r border-charcoal-750 pr-3"
          >
            <ArrowLeft className="w-3 h-3" />
            <span>STAR MAP</span>
          </button>

          <span className="text-[10px] font-pixel text-cosmic-orange">
            MOD {problem.moduleId}
          </span>
          <span className="text-[11px] text-slate-400 font-mono">
            LAB #{problemIndex + 1} OF {totalProblems}:
          </span>
          <span className="font-pixel text-[11px] text-slate-100 truncate max-w-[200px] sm:max-w-[340px]">
            {problem.title}
          </span>

          {isCurrentCleared && (
            <span className="hidden sm:flex items-center gap-1 text-cosmic-emerald text-[9px] font-pixel bg-emerald-950/60 border border-emerald-800/80 px-1.5 py-0.2 rounded ml-1">
              <CheckCircle2 className="w-3 h-3" /> CLEARED
            </span>
          )}
        </div>

        {/* Next Problem Button (With Glowing Cosmic Highlight) */}
        <button
          onClick={() => {
            if (hasNextProblem) {
              soundFx.playClick();
              onNextProblem();
            }
          }}
          disabled={!hasNextProblem}
          className="flex items-center gap-1 px-3.5 py-1 rounded-lg bg-charcoal-950 border border-cosmic-orange/60 text-cosmic-orange hover:bg-cosmic-orange hover:text-charcoal-950 font-pixel text-[10px] font-bold shadow-glow-orange disabled:opacity-30 disabled:pointer-events-none transition-all"
        >
          <span>NEXT LAB</span>
          <ChevronRight className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Main Split-Pane Workspace Body */}
      <div 
        ref={containerRef}
        className={`relative flex-1 flex flex-col md:flex-row overflow-hidden ${
          isDragging ? 'cursor-col-resize' : ''
        }`}
      >
        {/* Mobile View Toggle */}
        <div className="flex md:hidden items-center justify-between bg-charcoal-900 border-b border-charcoal-750 px-3 py-1.5 text-xs font-retro">
          <div className="flex items-center gap-1 bg-charcoal-950 p-1 rounded-lg border border-charcoal-800 w-full justify-center">
            <button
              onClick={() => setIsMobileTab('spec')}
              className={`flex-1 py-1 rounded text-[10px] font-pixel text-center ${isMobileTab === 'spec' ? 'bg-cosmic-cyan text-charcoal-950 font-bold' : 'text-slate-400'}`}
            >
              PROBLEM
            </button>
            <button
              onClick={() => setIsMobileTab('editor')}
              className={`flex-1 py-1 rounded text-[10px] font-pixel text-center ${isMobileTab === 'editor' ? 'bg-cosmic-orange text-charcoal-950 font-bold' : 'text-slate-400'}`}
            >
              CODE & TEST
            </button>
          </div>
        </div>

        {/* ================= LEFT PANE: Problem Statement Panel ================= */}
        <div 
          style={{ width: `${splitRatio}%` }}
          className={`h-full flex-col border-r border-charcoal-750 bg-charcoal-900/95 overflow-hidden ${
            isMobileTab === 'spec' ? 'flex w-full md:w-auto' : 'hidden md:flex'
          }`}
        >
          {/* Panel Header */}
          <div className="h-10 px-4 bg-charcoal-950 border-b border-charcoal-750 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-cosmic-cyan animate-pulse" />
              <h2 className="text-xs font-pixel text-slate-100 truncate max-w-[200px] sm:max-w-[260px]">
                {problem.title}
              </h2>
            </div>
            <span className="text-[10px] font-retro px-2 py-0.5 rounded bg-cosmic-orange/20 border border-cosmic-orange text-cosmic-orange">
              +{problem.xpReward} XP
            </span>
          </div>

          {/* Tab Switcher: Problem Briefing / Hints */}
          <div className="flex items-center border-b border-charcoal-750 bg-charcoal-900 text-xs font-retro">
            <button
              onClick={() => { soundFx.playClick(); setActiveTab('problem'); }}
              className={`flex-1 py-2 text-center transition-colors ${
                activeTab === 'problem'
                  ? 'border-b-2 border-cosmic-cyan text-cosmic-cyan font-bold bg-charcoal-850'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              BRIEFING & SPECS
            </button>
            <button
              onClick={() => { soundFx.playClick(); setActiveTab('hints'); }}
              className={`flex-1 py-2 text-center transition-colors flex items-center justify-center gap-1.5 ${
                activeTab === 'hints'
                  ? 'border-b-2 border-cosmic-amber text-cosmic-amber font-bold bg-charcoal-850'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              <HelpCircle className="w-3.5 h-3.5" />
              <span>HINTS ({unlockedHintLevels.length}/{problem.hints.length})</span>
            </button>
          </div>

          {/* Panel Body: Scrollable Content */}
          <div className="flex-1 overflow-y-auto p-4 text-xs text-slate-300 font-retro space-y-4">
            {activeTab === 'problem' ? (
              <>
                <div className="flex items-center justify-between bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                  <span className="text-slate-400">SYLLABUS REF:</span>
                  <span className="text-cosmic-cyan font-semibold">{problem.syllabusRef}</span>
                </div>

                <div className="space-y-2">
                  <h3 className="font-pixel text-[10px] text-cosmic-cyan tracking-wider">
                    MISSION OBJECTIVE
                  </h3>
                  <p className="leading-relaxed whitespace-pre-wrap text-slate-200">
                    {problem.description}
                  </p>
                </div>

                <div className="space-y-2.5">
                  <div className="bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                    <span className="font-pixel text-[9px] text-cosmic-amber block mb-1">
                      INPUT FORMAT:
                    </span>
                    <p className="text-slate-300">{problem.inputFormat}</p>
                  </div>

                  <div className="bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                    <span className="font-pixel text-[9px] text-cosmic-amber block mb-1">
                      OUTPUT FORMAT:
                    </span>
                    <p className="text-slate-300 whitespace-pre-wrap">{problem.outputFormat}</p>
                  </div>

                  <div className="bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                    <span className="font-pixel text-[9px] text-cosmic-orange block mb-1">
                      CONSTRAINTS:
                    </span>
                    <p className="text-slate-300 font-mono text-[11px] whitespace-pre-wrap">{problem.constraints}</p>
                  </div>
                </div>

                {/* Sample I/O */}
                <div className="space-y-2">
                  <h3 className="font-pixel text-[10px] text-cosmic-cyan tracking-wider">
                    SAMPLE TELEMETRY
                  </h3>
                  <div className="grid grid-cols-1 gap-2.5">
                    <div className="bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                      <span className="text-[9px] text-slate-400 block mb-1 font-pixel">SAMPLE INPUT</span>
                      <pre className="font-mono text-cosmic-cyan text-[11px] whitespace-pre-wrap">{problem.sampleInput}</pre>
                    </div>
                    <div className="bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                      <span className="text-[9px] text-slate-400 block mb-1 font-pixel">SAMPLE OUTPUT</span>
                      <pre className="font-mono text-cosmic-emerald text-[11px] whitespace-pre-wrap">{problem.sampleOutput}</pre>
                    </div>
                  </div>
                </div>
              </>
            ) : (
              /* Tiered Hint System */
              <div className="space-y-3">
                <div className="flex items-center gap-3 bg-charcoal-950 p-3 rounded-xl border border-charcoal-800">
                  <img 
                    src="/sprites/astronaut_hint.png" 
                    alt="Hint" 
                    style={{ width: '40px', height: '40px', maxWidth: '40px', maxHeight: '40px' }}
                    className="object-contain pixelated" 
                  />
                  <div>
                    <h4 className="font-pixel text-[10px] text-cosmic-amber">TIERED HINT TRANSMISSION</h4>
                    <p className="text-[11px] text-slate-400 mt-0.5">
                      Hints provide algorithmic assistance at the cost of XP.
                    </p>
                  </div>
                </div>

                {problem.hints.map((hint) => {
                  const isUnlocked = unlockedHintLevels.includes(hint.level);
                  return (
                    <div 
                      key={hint.level}
                      className={`p-3 rounded-xl border transition-all ${
                        isUnlocked ? 'bg-charcoal-850 border-cosmic-amber/50' : 'bg-charcoal-950 border-charcoal-800'
                      }`}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="font-pixel text-[10px] text-slate-300">
                          HINT LEVEL #{hint.level}
                        </span>
                        {!isUnlocked ? (
                          <button
                            onClick={() => handleUnlockHint(hint)}
                            className="flex items-center gap-1 px-2.5 py-1 rounded bg-cosmic-orange/20 border border-cosmic-orange text-cosmic-orange text-[9px] font-pixel hover:bg-cosmic-orange hover:text-charcoal-950 transition-colors"
                          >
                            <Zap className="w-3 h-3" />
                            <span>UNLOCK (-{hint.cost} XP)</span>
                          </button>
                        ) : (
                          <span className="text-[9px] font-pixel text-cosmic-emerald">
                            UNLOCKED
                          </span>
                        )}
                      </div>

                      {isUnlocked ? (
                        <p className="text-slate-200 leading-relaxed font-retro text-xs">
                          {hint.text}
                        </p>
                      ) : (
                        <div className="h-8 bg-charcoal-900/60 rounded flex items-center justify-center text-slate-500 text-[10px] italic">
                          Encrypted hint transmission.
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* ================= DRAGGABLE SPLIT HANDLE ================= */}
        <div
          onPointerDown={handlePointerDown}
          className="hidden md:flex relative w-2 h-full bg-charcoal-900 hover:bg-cosmic-cyan/50 active:bg-cosmic-cyan items-center justify-center cursor-col-resize transition-colors z-20 group"
          title="Drag to resize (φ snap)"
        >
          <div className="flex flex-col items-center gap-1">
            <div className="w-0.5 h-3 rounded bg-slate-600 group-hover:bg-charcoal-950" />
            <div className="w-0.5 h-3 rounded bg-slate-600 group-hover:bg-charcoal-950" />
          </div>

          <div className="absolute top-2 left-1/2 -translate-x-1/2 hidden group-hover:flex items-center gap-1 bg-charcoal-950 border border-cosmic-cyan px-2 py-0.5 rounded text-[8px] font-pixel text-cosmic-cyan whitespace-nowrap shadow-xl z-30">
            <button onClick={(e) => { e.stopPropagation(); snapToGoldenRatio(); }} className="hover:underline">
              φ (38.2%)
            </button>
            <span>|</span>
            <button onClick={(e) => { e.stopPropagation(); snapToEqual(); }} className="hover:underline">
              50%
            </button>
          </div>
        </div>

        {/* ================= RIGHT PANE: Code Editor & Console ================= */}
        <div 
          style={{ width: `${100 - splitRatio}%` }}
          className={`h-full flex-col bg-charcoal-950 overflow-hidden ${
            isMobileTab === 'editor' ? 'flex w-full md:w-auto' : 'hidden md:flex'
          }`}
        >
          {/* Editor Action Bar */}
          <div className="h-10 px-3 sm:px-4 bg-charcoal-950 border-b border-charcoal-750 flex items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <FileCode className="w-4 h-4 text-cosmic-orange" />
              <span className="text-xs font-mono text-slate-300">
                main.c (C17 / GCC)
              </span>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => { soundFx.playClick(); setActiveTab('hints'); setIsMobileTab('spec'); }}
                className="flex items-center gap-1 px-2.5 py-1 rounded bg-charcoal-900 hover:bg-charcoal-850 border border-charcoal-750 text-xs font-retro text-cosmic-amber transition-colors"
              >
                <HelpCircle className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">HINT</span>
              </button>

              <button
                onClick={() => {
                  soundFx.playClick();
                  if (confirm('Reset to starter C code?')) setCode(problem.starterCode);
                }}
                className="p-1 rounded bg-charcoal-900 hover:bg-charcoal-850 border border-charcoal-750 text-slate-400 hover:text-slate-200 transition-colors"
                title="Reset Code Template"
              >
                <RotateCcw className="w-3.5 h-3.5" />
              </button>

              <button
                disabled={isEvaluating}
                onClick={() => handleExecute(false)}
                className="flex items-center gap-1.5 px-3 py-1 rounded bg-charcoal-850 hover:bg-charcoal-800 border border-charcoal-700 text-xs font-retro text-slate-200 transition-colors disabled:opacity-50"
              >
                <Play className="w-3.5 h-3.5 text-cosmic-cyan" />
                <span>TEST</span>
              </button>

              <button
                disabled={isEvaluating}
                onClick={() => handleExecute(true)}
                className="flex items-center gap-1.5 px-3.5 py-1 rounded bg-cosmic-orange hover:bg-orange-500 text-charcoal-950 text-xs font-pixel font-bold shadow-glow-orange transition-all disabled:opacity-50"
              >
                <Send className="w-3.5 h-3.5" />
                <span>{isEvaluating ? 'RUNNING' : 'SUBMIT'}</span>
              </button>
            </div>
          </div>

          {/* Monaco Editor Container */}
          <div className="flex-1 relative overflow-hidden bg-charcoal-950 min-h-[200px]">
            <Editor
              height="100%"
              defaultLanguage="c"
              language="c"
              theme="vs-dark"
              value={code}
              onChange={(val) => {
                setCode(val || '');
                soundFx.playType();
              }}
              options={{
                fontSize: 13,
                fontFamily: "'Fira Code', 'JetBrains Mono', Consolas, monospace",
                minimap: { enabled: false },
                scrollBeyondLastLine: false,
                automaticLayout: true,
                tabSize: 4,
                insertSpaces: true,
                lineNumbers: 'on',
                padding: { top: 8, bottom: 8 }
              }}
            />
          </div>

          {/* Lower Test Execution Console with Next Problem Victory Prompt */}
          <div className="h-56 border-t border-charcoal-750 bg-charcoal-900/98 flex flex-col">
            {/* Console Header */}
            <div className="h-9 px-4 bg-charcoal-950 border-b border-charcoal-750 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Terminal className="w-3.5 h-3.5 text-cosmic-cyan" />
                <span className="text-[11px] font-pixel text-slate-200">
                  EVALUATION CONSOLE
                </span>
                {evalResult && (
                  <span className={`text-[9px] font-pixel px-1.5 py-0.2 rounded ml-2 ${
                    evalResult.allPassed 
                      ? 'bg-cosmic-emerald/20 text-cosmic-emerald border border-cosmic-emerald/50'
                      : 'bg-red-950/60 text-red-400 border border-red-800/60'
                  }`}>
                    {evalResult.allPassed ? 'ALL TESTS PASSED' : 'TESTS FAILED'}
                  </span>
                )}
              </div>

              {/* Action and Astronaut Reaction Avatar */}
              <div className="flex items-center gap-2">
                {evalResult?.allPassed && hasNextProblem && (
                  <button
                    onClick={() => {
                      soundFx.playClick();
                      onNextProblem();
                    }}
                    className="flex items-center gap-1 px-2.5 py-1 rounded bg-cosmic-emerald hover:bg-emerald-400 text-charcoal-950 font-pixel text-[9px] font-bold shadow-glow-emerald transition-all animate-bounce"
                  >
                    <span>NEXT LAB &gt;&gt;</span>
                  </button>
                )}

                <img 
                  src={astronautReaction} 
                  alt="Reaction" 
                  style={{ width: '28px', height: '28px', maxWidth: '28px', maxHeight: '28px' }}
                  className="object-contain pixelated" 
                />
              </div>
            </div>

            {/* Test Case Breakdown */}
            <div className="flex-1 overflow-y-auto p-3 text-xs font-mono">
              {evalResult ? (
                evalResult.compilationError ? (
                  <div className="p-2.5 bg-red-950/40 border border-red-800/60 rounded-xl text-red-300 space-y-1">
                    <div className="flex items-center gap-1.5 font-pixel text-[10px] text-red-400">
                      <AlertTriangle className="w-3.5 h-3.5" />
                      <span>SYNTAX / COMPILATION ERROR</span>
                    </div>
                    <pre className="text-xs whitespace-pre-wrap">{evalResult.compilationError}</pre>
                  </div>
                ) : (
                  <div className="space-y-2.5">

                    {/* Victory Banner if all tests passed */}
                    {evalResult.allPassed && (
                      <div className="p-2.5 rounded-xl bg-emerald-950/40 border border-cosmic-emerald/60 flex items-center justify-between text-xs font-retro">
                        <div className="flex items-center gap-2">
                          <Sparkles className="w-4 h-4 text-cosmic-emerald animate-pulse" />
                          <span className="font-pixel text-[10px] text-cosmic-emerald">
                            SOLVED! +{evalResult.earnedXp} XP EARNED
                          </span>
                        </div>
                        {hasNextProblem ? (
                          <button
                            onClick={() => {
                              soundFx.playClick();
                              onNextProblem();
                            }}
                            className="flex items-center gap-1.5 px-3 py-1 rounded bg-cosmic-emerald text-charcoal-950 font-pixel text-[10px] font-bold hover:bg-emerald-400 transition-colors shadow-glow-emerald"
                          >
                            <span>PROCEED TO NEXT LAB</span>
                            <ChevronRight className="w-3.5 h-3.5" />
                          </button>
                        ) : (
                          <span className="font-pixel text-[10px] text-cosmic-amber">
                            🎉 FINAL CURRICULUM PROBLEM CLEARED!
                          </span>
                        )}
                      </div>
                    )}

                    <div className="flex items-center gap-1.5 overflow-x-auto pb-0.5">
                      {evalResult.results.map((tc, idx) => (
                        <button
                          key={tc.id}
                          onClick={() => { soundFx.playClick(); setSelectedTestCaseIdx(idx); }}
                          className={`flex items-center gap-1 px-2.5 py-1 rounded-lg border text-xs font-retro transition-colors ${
                            selectedTestCaseIdx === idx
                              ? 'bg-charcoal-800 border-cosmic-cyan text-cosmic-cyan'
                              : 'bg-charcoal-950 border-charcoal-800 text-slate-400'
                          }`}
                        >
                          {tc.passed ? (
                            <CheckCircle className="w-3 h-3 text-cosmic-emerald" />
                          ) : (
                            <XCircle className="w-3 h-3 text-rose-500" />
                          )}
                          <span>{tc.desc}</span>
                        </button>
                      ))}
                    </div>

                    {evalResult.results[selectedTestCaseIdx] && (
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-2.5 bg-charcoal-950 p-2.5 rounded-xl border border-charcoal-800">
                        <div>
                          <span className="text-[9px] font-pixel text-slate-400 block mb-0.5">INPUT</span>
                          <pre className="bg-charcoal-900 p-1.5 rounded text-slate-300 whitespace-pre-wrap text-[11px]">
                            {evalResult.results[selectedTestCaseIdx].input}
                          </pre>
                        </div>

                        <div>
                          <span className="text-[9px] font-pixel text-slate-400 block mb-0.5">EXPECTED OUTPUT</span>
                          <pre className="bg-charcoal-900 p-1.5 rounded text-cosmic-emerald whitespace-pre-wrap text-[11px]">
                            {evalResult.results[selectedTestCaseIdx].expectedOutput}
                          </pre>
                        </div>

                        <div>
                          <span className="text-[9px] font-pixel text-slate-400 block mb-0.5">YOUR OUTPUT</span>
                          <pre className={`p-1.5 rounded whitespace-pre-wrap text-[11px] ${
                            evalResult.results[selectedTestCaseIdx].passed
                              ? 'bg-charcoal-900 text-cosmic-emerald'
                              : 'bg-red-950/40 text-red-300 border border-red-800/50'
                          }`}>
                            {evalResult.results[selectedTestCaseIdx].actualOutput}
                          </pre>
                        </div>
                      </div>
                    )}
                  </div>
                )
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-500 font-retro">
                  <span className="text-[11px]">Ready to evaluate. Press [SUBMIT] or [TEST].</span>
                </div>
              )}
            </div>
          </div>

        </div>

      </div>

    </div>
  );
}

